function applyWalletTheme() {
  if (state.partnerProfile) {
    document.body.classList.add('shared-wallet-active');

    // Replace wallet icon in header with user group
    const icon = document.getElementById('header-wallet-icon');
    if (icon) {
      icon.className = 'fa-solid fa-people-roof';
    }
  } else {
    document.body.classList.remove('shared-wallet-active');

    // Restore wallet icon in header
    const icon = document.getElementById('header-wallet-icon');
    if (icon) {
      icon.className = 'fa-solid fa-wallet';
    }
  }

  // IMPORTANT: Always re-apply the user's chosen theme so that shared-wallet-active
  // never overrides the colour scheme. The theme is the single source of truth for colours.
  const savedTheme = localStorage.getItem('app_theme') || 'dark';
  document.body.classList.remove('theme-oled', 'theme-light', 'theme-emerald', 'theme-ocean', 'theme-pink');
  if (savedTheme !== 'dark') {
    document.body.classList.add(`theme-${savedTheme}`);
  }
}


// Bind to window
window.applyWalletTheme = applyWalletTheme;

function getActiveTransactions() {
  const currentUserId = state.currentUser ? state.currentUser.id : null;
  const partnerId = state.partnerProfile ? state.partnerProfile.id : null;
  const familyId = state.userProfile ? state.userProfile.family_id : null;

  const filtered = state.transactions.filter(t => {
    if (t.user_id === undefined) {
      return true;
    }

    if (currentUserId) {
      if (familyId) {
        return t.family_id === familyId ||
          t.user_id === currentUserId ||
          t.user_id === partnerId ||
          (t.id && String(t.id).startsWith('local_'));
      }
      return t.user_id === currentUserId ||
        t.user_id === partnerId ||
        (t.id && String(t.id).startsWith('local_'));
    } else {
      return t.user_id === null || t.user_id === undefined;
    }
  });

  // Deduplicate: (1) ID-based to remove exact duplicates, then
  // (2) content-based to remove local_ copies that were synced to cloud
  const seenIds = new Set();
  const idDeduped = filtered.filter(t => {
    const id = t.id;
    if (!id) return true;
    if (seenIds.has(id)) return false;
    seenIds.add(id);
    return true;
  });

  const cloudKeys = new Set();
  const locals = [];
  const others = [];
  idDeduped.forEach(t => {
    if (t.id && String(t.id).startsWith('local_')) {
      locals.push(t);
    } else {
      // Include user_id so that Marios & Vasoula identical transactions are NOT merged
      const key = `${t.user_id || 'unknown'}|${t.amount || 0}|${String(t.date || '').split('T')[0]}|${t.type || ''}|${t.category || ''}|${t.account_from || ''}`;
      cloudKeys.add(key);
      others.push(t);
    }
  });
  const dedupedLocals = locals.filter(t => {
    const key = `${t.user_id || 'unknown'}|${t.amount || 0}|${String(t.date || '').split('T')[0]}|${t.type || ''}|${t.category || ''}|${t.account_from || ''}`;
    return !cloudKeys.has(key);
  });
  return [...others, ...dedupedLocals];
}

function calculateInitialBalances() {
  if (!state.accounts) return;
  state.accounts.forEach(acc => {
    let netSum = 0;
    // Base balance is calculated from all active transactions going backwards
    const activeTrans = getActiveTransactions();
    activeTrans.forEach(t => {
      const amt = CurrencyService.toBase(t);
      if (t.type === 'transfer') {
        if (t.account_from === acc.name) netSum -= amt;
        if (t.account_to === acc.name) netSum += amt;
      } else {
        if (t.account_from === acc.name) {
          if (t.type === 'expense') netSum -= amt;
          else if (t.type === 'income') netSum += amt;
        }
      }
    });
    acc.initial_balance = sanitizeFloat((parseFloat(acc.balance) || 0) - netSum);
  });
}

function normalizeString(str) {
  if (!str) return '';
  let s = String(str).toLowerCase().trim();
  const map = {
    'ά': 'α', 'έ': 'ε', 'ή': 'η', 'ί': 'ι', 'ό': 'ο', 'ύ': 'υ', 'ώ': 'ω',
    'ΐ': 'ι', 'ΰ': 'υ', 'ϊ': 'ι', 'ϋ': 'υ'
  };
  let res = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    res += map[c] || c;
  }
  return res.toUpperCase();
}

function classifyCategory(categoryName) {
  const norm = normalizeString(categoryName);
  const essentialKeywords = [
    'ΣΠΙΤΙ', 'HOME', 'RENT', 'ΕΝΟΙΚΙΟ',
    'ΔΙΑΤΡΟΦΗ', 'FOOD', 'SUPERMARKET', 'ΣΟΥΠΕΡ ΜΑΡΚΕΤ', 'ΣΟΥΠΕΡΜΑΡΚΕΤ',
    'ΥΓΕΙΑ', 'HEALTH', 'PHARMACY', 'ΦΑΡΜΑΚΕΙΟ', 'ΓΙΑΤΡΟΣ',
    'ΦΟΡΟΙ', 'TAXES', 'ΛΟΓΙΣΤΗΣ', 'ACCOUNTANT',
    'ΜΕΤΑΚΙΝΗΣΗ', 'TRANSIT', 'METRO', 'ΛΕΩΦΟΡΕΙΟ', 'BUS', 'ΣΥΓΚΟΙΝΩΝΙΕΣ'
  ];
  const isEssential = essentialKeywords.some(kw => norm.includes(kw));
  return {
    isEssential: isEssential,
    isLifestyle: !isEssential
  };
}

/**
 * Calculates the Financial Health Score (1-100)
 */
function calculateFinancialHealthScore(transactions, accounts, hasHistoricalData) {
  const today = new Date();
  const currentYear = today.getFullYear();
  const currentMonth = today.getMonth(); // 0-11

  // Filter current month transactions (excluding transfers)
  const currentMonthTrans = transactions.filter(t => {
    if (!t.date || t.type === 'transfer') return false;
    const datePart = String(t.date || '').split('T')[0].split(' ')[0];
    const parts = datePart.split('-');
    if (parts.length !== 3) return false;
    const y = parseInt(parts[0], 10);
    const m = parseInt(parts[1], 10) - 1; // 0-11
    return y === currentYear && m === currentMonth;
  });

  // Calculate current month's income and expense
  let currentMonthIncome = 0;
  let currentMonthExpense = 0;
  currentMonthTrans.forEach(t => {
    const amt = CurrencyService.toBase(t);
    if (t.type === 'income') currentMonthIncome += amt;
    if (t.type === 'expense') currentMonthExpense += amt;
  });

  // --- CRITERION 1: Savings Rate (40%) ---
  let savingsRateScore = 0;
  let savingsRate = 0;
  if (currentMonthIncome > 0) {
    savingsRate = (currentMonthIncome - currentMonthExpense) / currentMonthIncome;
    if (savingsRate >= 0.40) {
      savingsRateScore = 100;
    } else if (savingsRate > 0) {
      if (savingsRate <= 0.10) {
        savingsRateScore = (savingsRate / 0.10) * 50;
      } else if (savingsRate <= 0.20) {
        savingsRateScore = 50 + ((savingsRate - 0.10) / 0.10) * 30;
      } else {
        savingsRateScore = 80 + ((savingsRate - 0.20) / 0.20) * 20;
      }
    } else {
      savingsRateScore = 0;
    }
  } else {
    savingsRateScore = currentMonthExpense > 0 ? 0 : 50; // Neutral if no activity
  }

  // --- CRITERION 2: Emergency Fund (40%) ---
  // Calculate liquid balance as the net balance (income - expense) of the target year (currentYear)
  const targetYearTrans = transactions.filter(t => {
    if (!t.date || t.type === 'transfer') return false;
    const parts = String(t.date).split('T')[0].split(' ')[0].split('-');
    if (parts.length !== 3) return false;
    return parseInt(parts[0], 10) === currentYear;
  });

  let targetYearIncome = 0;
  let targetYearExpense = 0;
  targetYearTrans.forEach(t => {
    const amt = CurrencyService.toBase(t);
    if (t.type === 'income') targetYearIncome += amt;
    if (t.type === 'expense') targetYearExpense += amt;
  });

  const currentBankBalance = targetYearIncome - targetYearExpense;

  // Compute average monthly expenses (all and essential)
  let avgMonthlyExpense = 0;
  let avgEssentialMonthlyExpense = 0;

  // Let's compute current month's essential expenses
  let currentMonthEssentialExpense = 0;
  currentMonthTrans.forEach(t => {
    const amt = CurrencyService.toBase(t);
    if (t.type === 'expense') {
      const cls = classifyCategory(t.category);
      if (cls.isEssential) {
        currentMonthEssentialExpense += amt;
      }
    }
  });

  if (hasHistoricalData) {
    const monthlyExpensesMap = {};
    const monthlyEssentialMap = {};

    transactions.forEach(t => {
      if (t.type !== 'expense' || !t.date) return;
      const datePart = String(t.date || '').split('T')[0].split(' ')[0];
      const parts = datePart.split('-');
      if (parts.length !== 3) return;
      const y = parseInt(parts[0], 10);
      const m = parseInt(parts[1], 10) - 1;

      // Restrict historical data strictly to current calendar year
      if (y !== currentYear) return;
      // Exclude current month
      if (y === currentYear && m === currentMonth) return;

      const key = `${y}-${m}`;
      const amt = CurrencyService.toBase(t);

      monthlyExpensesMap[key] = (monthlyExpensesMap[key] || 0) + amt;

      const cls = classifyCategory(t.category);
      if (cls.isEssential) {
        monthlyEssentialMap[key] = (monthlyEssentialMap[key] || 0) + amt;
      }
    });

    // Stable divisor: count actual elapsed months since the first expense of the current year up to the previous month
    let firstActiveMonth = currentMonth;
    transactions.forEach(t => {
      if (!t.date || t.type !== 'expense') return;
      const datePart = String(t.date || '').split('T')[0].split(' ')[0];
      const parts = datePart.split('-');
      if (parts.length !== 3) return;
      const y = parseInt(parts[0], 10);
      const m = parseInt(parts[1], 10) - 1;
      if (y === currentYear && m < firstActiveMonth) {
        firstActiveMonth = m;
      }
    });

    const elapsedMonthsInYear = currentMonth - firstActiveMonth;
    const monthsCount = Math.max(1, elapsedMonthsInYear);

    const totalHistoricalExpense = Object.values(monthlyExpensesMap).reduce((a, b) => a + b, 0);
    avgMonthlyExpense = totalHistoricalExpense / monthsCount;

    const totalHistoricalEssential = Object.values(monthlyEssentialMap).reduce((a, b) => a + b, 0);
    avgEssentialMonthlyExpense = totalHistoricalEssential / monthsCount;
  } else {
    avgMonthlyExpense = currentMonthExpense;
    avgEssentialMonthlyExpense = currentMonthEssentialExpense;
  }

  if (avgMonthlyExpense <= 0) avgMonthlyExpense = 1000; // reasonable fallback
  if (avgEssentialMonthlyExpense <= 0) avgEssentialMonthlyExpense = avgMonthlyExpense * 0.75; // fallback to 75%
  if (avgEssentialMonthlyExpense > avgMonthlyExpense) avgEssentialMonthlyExpense = avgMonthlyExpense;

  const monthsCovered = currentBankBalance / avgMonthlyExpense;
  const survivalRunway = currentBankBalance / avgEssentialMonthlyExpense;
  const lifestyleRunway = monthsCovered;

  let emergencyFundScore = 0;
  if (monthsCovered >= 12) {
    emergencyFundScore = 100;
  } else if (monthsCovered > 0) {
    if (monthsCovered <= 3) {
      emergencyFundScore = (monthsCovered / 3) * 50;
    } else if (monthsCovered <= 6) {
      emergencyFundScore = 50 + ((monthsCovered - 3) / 3) * 30;
    } else {
      emergencyFundScore = 80 + ((monthsCovered - 6) / 6) * 20;
    }
  } else {
    emergencyFundScore = 0;
  }

  // --- CRITERION 3: Expense Trend (20%) ---
  let expenseTrendScore = 0;
  let isTemporary = false;

  if (hasHistoricalData) {
    const prevMonthDate = new Date(currentYear, currentMonth - 1, 1);
    const prevYearNum = prevMonthDate.getFullYear();
    const prevMonthNum = prevMonthDate.getMonth();

    let prevMonthExpense = 0;
    transactions.forEach(t => {
      if (t.type === 'expense' && t.date) {
        const datePart = String(t.date || '').split('T')[0].split(' ')[0];
        const parts = datePart.split('-');
        if (parts.length !== 3) return;
        const y = parseInt(parts[0], 10);
        const m = parseInt(parts[1], 10) - 1;
        if (y === prevYearNum && m === prevMonthNum) {
          prevMonthExpense += CurrencyService.toBase(t);
        }
      }
    });

    if (prevMonthExpense > 0) {
      if (currentMonthExpense <= prevMonthExpense) {
        expenseTrendScore = 100;
      } else {
        const pctIncrease = (currentMonthExpense - prevMonthExpense) / prevMonthExpense;
        expenseTrendScore = Math.max(0, 100 - (pctIncrease * 200));
      }
    } else {
      expenseTrendScore = currentMonthExpense <= currentMonthIncome ? 100 : 50;
    }
  } else {
    isTemporary = true;
    if (currentMonthExpense < currentMonthIncome) {
      expenseTrendScore = 100;
    } else {
      expenseTrendScore = 30;
    }
  }

  let finalScore = (savingsRateScore * 0.40) + (emergencyFundScore * 0.40) + (expenseTrendScore * 0.20);
  finalScore = Math.min(100, Math.max(0, finalScore));

  let label = '';
  const lang = state.lang || 'el';
  if (lang === 'el') {
    if (finalScore >= 85) label = 'Εξαιρετική Οικονομική Υγεία';
    else if (finalScore >= 70) label = 'Καλή Οικονομική Υγεία';
    else if (finalScore >= 50) label = 'Μέτρια Οικονομική Υγεία';
    else label = 'Χρειάζεται Προσοχή';
  } else {
    if (finalScore >= 85) label = 'Excellent Financial Health';
    else if (finalScore >= 70) label = 'Good Financial Health';
    else if (finalScore >= 50) label = 'Average Financial Health';
    else label = 'Needs Attention';
  }

  return {
    score: finalScore,
    label: label,
    isTemporary: isTemporary,
    savingsRateScore: savingsRateScore,
    emergencyFundScore: emergencyFundScore,
    expenseTrendScore: expenseTrendScore,
    weightedSavings: savingsRateScore * 0.4,
    weightedEmergency: emergencyFundScore * 0.4,
    weightedTrend: expenseTrendScore * 0.2,
    monthsCovered: monthsCovered,
    savingsRate: savingsRate,
    survivalRunway: survivalRunway,
    lifestyleRunway: lifestyleRunway,
    liquidBalance: currentBankBalance
  };
}

/**
 * Calculates Year-End Forecasting (Run-Rate)
 */
function calculateForecasting(transactions, hasHistoricalData) {
  const today = new Date();
  const currentYear = today.getFullYear();
  const currentMonth = today.getMonth(); // 0-11

  // Filter current year transactions (excluding transfers)
  const currentYearTrans = transactions.filter(t => {
    if (!t.date || t.type === 'transfer') return false;
    const datePart = String(t.date || '').split('T')[0].split(' ')[0];
    const parts = datePart.split('-');
    if (parts.length !== 3) return false;
    const y = parseInt(parts[0], 10);
    return y === currentYear;
  });

  let currentYearIncome = 0;
  let currentYearExpense = 0;
  currentYearTrans.forEach(t => {
    const amt = CurrencyService.toBase(t);
    if (t.type === 'income') currentYearIncome += amt;
    if (t.type === 'expense') currentYearExpense += amt;
  });

  const currentYearSavings = currentYearIncome - currentYearExpense;
  const lang = state.lang || 'el';

  // Handle December case (Year-End Review)
  if (currentMonth === 11) {
    if (!hasHistoricalData) {
      const juneTrans = currentYearTrans.filter(t => {
        const datePart = String(t.date || '').split('T')[0].split(' ')[0];
        const parts = datePart.split('-');
        if (parts.length !== 3) return false;
        const m = parseInt(parts[1], 10) - 1;
        return m <= 5; // Jan to Jun
      });

      let juneIncome = 0;
      let juneExpense = 0;
      juneTrans.forEach(t => {
        const amt = CurrencyService.toBase(t);
        if (t.type === 'income') juneIncome += amt;
        if (t.type === 'expense') juneExpense += amt;
      });

      const juneSavings = juneIncome - juneExpense;
      const juneAvgMonthly = juneSavings / 6;
      const juneForecastProjection = juneSavings + (juneAvgMonthly * 6);

      const msg = lang === 'el'
        ? `Ολοκληρώθηκε ο πρώτος σας χρόνος! Η αρχική εκτίμηση του Ιουνίου προέβλεπε αποταμίευση € ${formatCurrency(juneForecastProjection)} και καταφέρατε να φτάσετε τα € ${formatCurrency(currentYearSavings)}. Είστε εντός στόχων!`
        : `Your first year is complete! The initial projection in June was € ${formatCurrency(juneForecastProjection)} and you achieved € ${formatCurrency(currentYearSavings)}. You are on track!`;

      return {
        isYearEnd: true,
        isNewUser: true,
        actualSavings: currentYearSavings,
        projectedSavings: juneForecastProjection,
        diff: currentYearSavings - juneForecastProjection,
        message: msg
      };
    } else {
      const prevYear = currentYear - 1;
      const prevYearTrans = transactions.filter(t => {
        if (!t.date || t.type === 'transfer') return false;
        const datePart = String(t.date || '').split('T')[0].split(' ')[0];
        const parts = datePart.split('-');
        if (parts.length !== 3) return false;
        const y = parseInt(parts[0], 10);
        return y === prevYear;
      });

      let prevYearIncome = 0;
      let prevYearExpense = 0;
      prevYearTrans.forEach(t => {
        const amt = CurrencyService.toBase(t);
        if (t.type === 'income') prevYearIncome += amt;
        if (t.type === 'expense') prevYearExpense += amt;
      });

      const prevYearSavings = prevYearIncome - prevYearExpense;
      const pctDiff = prevYearSavings > 0
        ? ((currentYearSavings - prevYearSavings) / prevYearSavings) * 100
        : 0;

      const sign = pctDiff >= 0 ? '+' : '';
      const msg = lang === 'el'
        ? `Το ${prevYear} είχατε αποταμιεύσει € ${formatCurrency(prevYearSavings)}. Φέτος κλείσατε στα € ${formatCurrency(currentYearSavings)} (${sign}${pctDiff.toFixed(1)}%). Εξαιρετική εξέλιξη!`
        : `In ${prevYear} you saved € ${formatCurrency(prevYearSavings)}. This year you closed at € ${formatCurrency(currentYearSavings)} (${sign}${pctDiff.toFixed(1)}%). Great progress!`;

      return {
        isYearEnd: true,
        isNewUser: false,
        actualSavings: currentYearSavings,
        prevYearSavings: prevYearSavings,
        pctDiff: pctDiff,
        message: msg
      };
    }
  }

  const elapsedMonths = currentMonth + 1; // 1-indexed (June = 6)
  const avgMonthlyIncome = currentYearIncome / elapsedMonths;
  const avgMonthlyExpense = currentYearExpense / elapsedMonths;
  const avgMonthlySavings = currentYearSavings / elapsedMonths;
  const remainingMonths = 12 - elapsedMonths;
  const projectedYearEndSavings = currentYearSavings + (avgMonthlySavings * remainingMonths);

  // Best Case: expenses reduced by 15% for the remaining months
  const bestMonthlySavings = avgMonthlyIncome - (avgMonthlyExpense * 0.85);
  const bestCaseSavings = currentYearSavings + (bestMonthlySavings * remainingMonths);

  // Worst Case: expenses increased by 15% for the remaining months
  const worstMonthlySavings = avgMonthlyIncome - (avgMonthlyExpense * 1.15);
  const worstCaseSavings = currentYearSavings + (worstMonthlySavings * remainingMonths);

  return {
    isYearEnd: false,
    currentYearSavings: currentYearSavings,
    avgMonthlySavings: avgMonthlySavings,
    projectedSavings: projectedYearEndSavings,
    bestCaseSavings: bestCaseSavings,
    worstCaseSavings: worstCaseSavings,
    remainingMonths: remainingMonths
  };
}

// Bind to window
window.getActiveTransactions = getActiveTransactions;
window.calculateInitialBalances = calculateInitialBalances;
window.calculateFinancialHealthScore = calculateFinancialHealthScore;
window.calculateForecasting = calculateForecasting;

// Scan categories and transactions to clean up duplicates (e.g. Chinese characters)
async function cleanDuplicateCategories() {
  const targetCategoryName = '🧾ΦΟΡΟΙ/ΛΟΓΙΣΤΗΣ';

  // Find bad categories in the categories list
  const badCategories = state.categories.filter(c => c.name && (
    c.name.includes('茶') ||
    /[\u4e00-\u9fff]/.test(c.name) ||
    (c.name.includes('ΦΟΡΟΙ/ΛΟΓΙΣΤΗΣ') && c.name !== '🧾ΦΟΡΟΙ/ΛΟΓΙΣΤΗΣ')
  ));

  // Find bad category names in transactions
  const badCategoryNamesInTrans = new Set();
  state.transactions.forEach(t => {
    if (t.category && (
      t.category.includes('茶') ||
      /[\u4e00-\u9fff]/.test(t.category) ||
      (t.category.includes('ΦΟΡΟΙ/ΛΟΓΙΣΤΗΣ') && t.category !== '🧾ΦΟΡΟΙ/ΛΟΓΙΣΤΗΣ')
    )) {
      badCategoryNamesInTrans.add(t.category);
    }
  });

  if (badCategories.length === 0 && badCategoryNamesInTrans.size === 0) return;

  console.log('Duplicate categories cleanup: found bad categories in list:', badCategories, 'and in transactions:', Array.from(badCategoryNamesInTrans));

  let didChange = false;
  const isOnline = state.supabaseClient && state.currentUser;

  // 1. Process bad category names in transactions
  for (const badCatName of badCategoryNamesInTrans) {
    try {
      if (isOnline) {
        console.log(`Updating transactions from bad category name "${badCatName}" to "${targetCategoryName}" in Cloud`);
        await state.supabaseClient
          .from('transactions')
          .update({ category: targetCategoryName })
          .eq('category', badCatName);
      }

      // Update local state transactions
      state.transactions.forEach(t => {
        if (t.category === badCatName) {
          t.category = targetCategoryName;
        }
      });
      didChange = true;
    } catch (e) {
      console.error(`Error during transaction update for category name "${badCatName}":`, e);
    }
  }

  // 2. Process bad category objects from database list
  for (const badCat of badCategories) {
    try {
      if (isOnline) {
        console.log(`Updating transactions from bad category object name "${badCat.name}" to "${targetCategoryName}" in Cloud`);
        await state.supabaseClient
          .from('transactions')
          .update({ category: targetCategoryName })
          .eq('category', badCat.name);

        console.log(`Deleting bad category "${badCat.name}" (ID: ${badCat.id}) from Cloud`);
        await state.supabaseClient
          .from('categories')
          .delete()
          .eq('id', badCat.id);
      }

      // Update local state transactions (just in case)
      state.transactions.forEach(t => {
        if (t.category === badCat.name) {
          t.category = targetCategoryName;
        }
      });

      // Update local state categories
      state.categories = state.categories.filter(c => c.id !== badCat.id);
      didChange = true;
    } catch (e) {
      console.error(`Error cleaning up bad category object "${badCat.name}":`, e);
    }
  }

  if (didChange) {
    console.log('Cleanup completed successfully. Saving to offline storage and updating UI.');
    localStorage.setItem('offline_transactions', JSON.stringify(state.transactions));
    localStorage.setItem('offline_categories', JSON.stringify(state.categories));
    calculateInitialBalances();
    // Only call updateUI if we're not in the middle of a bulk sync operation
    // (which already schedules its own clean render at the end)
    if (typeof updateUI === 'function' && !_suppressRealtimeEvents) {
      updateUI();
    }
  }
}

// Scan transactions list and delete duplicate entries (both locally and in Cloud)
async function cleanDuplicateTransactions() {
  if (!state.transactions || state.transactions.length === 0) return;

  const groups = {};
  const localCleaned = [];
  const cloudDeleteIds = [];
  let didChangeLocal = false;

  // Group all transactions by their visual contents.
  // IMPORTANT: user_id is included in the key so that transactions from different
  // family members with the same amount/date/category are NOT treated as duplicates.
  state.transactions.forEach(t => {
    if (!t) return;
    const datePart = String(t.date || '').split('T')[0].split(' ')[0];
    const amount = parseFloat(t.amount) || 0;
    const type = t.type || '';
    const category = t.category || '';
    const accountFrom = t.account_from || '';
    const accountTo = t.account_to || '';
    const note = t.note || '';
    // Include user_id so family members' identical transactions are NOT merged
    const userId = t.user_id || 'unknown';
    const key = `${userId}|${datePart}|${amount.toFixed(2)}|${type}|${category}|${accountFrom}|${accountTo}|${note}`;

    if (!groups[key]) {
      groups[key] = [];
    }
    groups[key].push(t);
  });

  // Process groups to identify duplicates
  Object.keys(groups).forEach(key => {
    const list = groups[key];
    if (list.length === 1) {
      localCleaned.push(list[0]);
    } else {
      // Sort to determine which one to keep
      // Local pending items (starting with local_) come first because they are not yet synced.
      // Otherwise, keep the earliest created_at, or fallback to alphabetical ID comparison.
      list.sort((a, b) => {
        const aIsLocal = a.id && String(a.id).startsWith('local_');
        const bIsLocal = b.id && String(b.id).startsWith('local_');
        if (aIsLocal && !bIsLocal) return -1;
        if (!aIsLocal && bIsLocal) return 1;

        const timeA = a.created_at ? getTransactionTime({ created_at: a.created_at }) : 0;
        const timeB = b.created_at ? getTransactionTime({ created_at: b.created_at }) : 0;
        if (timeA !== timeB) return timeA - timeB;

        return String(a.id || '').localeCompare(String(b.id || ''));
      });

      const canonical = list[0];
      localCleaned.push(canonical);

      // All others are duplicates to be deleted
      for (let i = 1; i < list.length; i++) {
        const dupe = list[i];
        if (dupe.id) {
          if (!String(dupe.id).startsWith('local_')) {
            cloudDeleteIds.push(dupe.id);
          }
          didChangeLocal = true;
        }
      }
    }
  });

  if (didChangeLocal) {
    console.log(`[DEDUPLICATION] Cleaned up local transactions state. Removed ${cloudDeleteIds.length} duplicates from local cache.`);

    // Preserve sorting
    localCleaned.sort(compareTransactions);

    state.transactions = localCleaned;
    localStorage.setItem('offline_transactions', JSON.stringify(localCleaned));
    calculateInitialBalances();
    updateUI();
  }

  if (cloudDeleteIds.length > 0 && state.isSupabaseEnabled && state.supabaseClient && state.currentUser) {
    // Suppress realtime events during cleanup to prevent the DELETE operations
    // from triggering UI re-renders (flickering numbers).
    _suppressRealtimeEvents = true;
    try {
      console.log(`[DEDUPLICATION] Deleting ${cloudDeleteIds.length} duplicate transaction records from Cloud Database...`);
      for (let i = 0; i < cloudDeleteIds.length; i += 50) {
        const batch = cloudDeleteIds.slice(i, i + 50);
        const { error } = await state.supabaseClient
          .from('transactions')
          .delete()
          .in('id', batch)
          .eq('user_id', state.currentUser.id); // safety: only delete own transactions
        if (error) {
          console.error('[DEDUPLICATION] Cloud delete error:', error);
        } else {
          console.log(`[DEDUPLICATION] Successfully deleted batch of ${batch.length} duplicates from Cloud.`);
        }
      }
    } catch (e) {
      console.error('[DEDUPLICATION] Exception during cloud delete:', e);
    } finally {
      // Re-enable realtime events after a short delay (to let any in-flight events pass)
      setTimeout(() => { _suppressRealtimeEvents = false; }, 5000);
    }
  }
}

window.cleanDuplicateTransactions = cleanDuplicateTransactions;

function getPendingLocalTransactions(cachedTransactions) {
  if (!cachedTransactions || !Array.isArray(cachedTransactions)) return [];
  try {
    const queueStr = localStorage.getItem('money_manager_sync_queue');
    const queuedIds = new Set();
    if (queueStr) {
      const queue = JSON.parse(queueStr) || [];
      queue.forEach(item => {
        if (item.action === 'save' && item.payload && item.payload.id) {
          queuedIds.add(item.payload.id);
        }
      });
    }

    return cachedTransactions.filter(t => {
      if (!t || typeof t !== 'object') return false;
      if (!t.id) return true;
      if (String(t.id).startsWith('local_')) return true;
      if (t.user_id === null || t.user_id === undefined) return true;

      // Keep if in the offline sync queue (not yet successfully uploaded)
      if (queuedIds.has(t.id)) return true;

      // Keep if recently saved (within the grace window). This protects a just-saved
      // transaction from being dropped when a re-fetch races ahead of the cloud write
      // propagation, even after it has been dequeued from the sync queue.
      if (_recentlySavedTxIds && _recentlySavedTxIds.has(String(t.id))) return true;

      // If it is not a valid UUID, it is local
      const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
      if (!uuidRegex.test(String(t.id))) return true;

      return false;
    });
  } catch (e) {
    console.error('Error getting pending local transactions:', e);
    return [];
  }
}

// ============================================================
// DATA LOADING
// ============================================================
async function loadData() {
  // Cancel any pending realtime debounce timer to prevent stale DB events
  // from overwriting the fresh data we are about to fetch.
  if (_realtimeDebounceTimer) {
    clearTimeout(_realtimeDebounceTimer);
    _realtimeDebounceTimer = null;
    _pendingRealtimeEvents = [];
    console.log('[loadData] Cancelled stale realtime debounce before fetch.');
  }

  // PRIVACY/ISOLATION: In guest mode, never fetch or load a previous account's
  // personal data from the cloud. Guest mode always starts with a clean slate.
  if (state.guestMode) {
    loadOfflineData();
    updateHeaderSyncIcon('offline');
    return;
  }

  if (state.isSupabaseEnabled && state.supabaseClient && state.currentUser) {
    try {
      updateHeaderSyncIcon('syncing');

      // Process offline queue first (flushes offline deletes/saves) before fetching latest transactions
      await processSyncQueue({ skipReload: true });

      const userId = state.currentUser.id;
      const partnerId = state.partnerProfile ? state.partnerProfile.id : null;

      // Fetch categories & accounts first
      const familyId = state.userProfile ? state.userProfile.family_id : null;
      let catsQuery = state.supabaseClient.from('categories').select('*');
      let accsQuery = state.supabaseClient.from('accounts').select('*');
      let tempsQuery = state.supabaseClient.from('recurring_templates').select('*');

      if (familyId && partnerId) {
        const filter = `family_id.eq.${familyId},user_id.eq.${userId},user_id.eq.${partnerId}`;
        catsQuery = catsQuery.or(filter);
        accsQuery = accsQuery.or(filter);
        tempsQuery = tempsQuery.or(filter);
      } else if (familyId) {
        const filter = `family_id.eq.${familyId},user_id.eq.${userId}`;
        catsQuery = catsQuery.or(filter);
        accsQuery = accsQuery.or(filter);
        tempsQuery = tempsQuery.or(filter);
      } else if (partnerId) {
        const filter = `user_id.eq.${userId},user_id.eq.${partnerId}`;
        catsQuery = catsQuery.or(filter);
        accsQuery = accsQuery.or(filter);
        tempsQuery = tempsQuery.or(filter);
      } else {
        catsQuery = catsQuery.eq('user_id', userId);
        accsQuery = accsQuery.eq('user_id', userId);
        tempsQuery = tempsQuery.eq('user_id', userId);
      }

      const [catsRes, accsRes, tempsRes] = await promiseTimeout(
        Promise.all([
          catsQuery,
          accsQuery,
          tempsQuery.then(r => r, () => ({ data: [], error: null }))
        ]),
        15000
      );
      if (catsRes.error) throw catsRes.error;
      if (accsRes.error) throw accsRes.error;

      // Fetch all transactions with pagination (due to Supabase PostgREST default 1000 limit)
      let allTransactions = [];
      let page = 0;
      const pageSize = 1000;
      let hasMore = true;

      while (hasMore) {
        let transQuery = state.supabaseClient
          .from('transactions')
          .select('*')
          .eq('status', 'active')
          .order('date', { ascending: false })
          .order('id', { ascending: false })
          .range(page * pageSize, (page + 1) * pageSize - 1);

        if (familyId) {
          if (partnerId) {
            transQuery = transQuery.or(`family_id.eq.${familyId},user_id.eq.${userId},user_id.eq.${partnerId}`);
          } else {
            transQuery = transQuery.or(`family_id.eq.${familyId},user_id.eq.${userId}`);
          }
        } else if (partnerId) {
          transQuery = transQuery.or(`user_id.eq.${userId},user_id.eq.${partnerId}`);
        } else {
          transQuery = transQuery.eq('user_id', userId);
        }

        const { data: pageData, error: pageErr } = await promiseTimeout(
          transQuery,
          15000
        );
        if (pageErr) throw pageErr;

        if (pageData && pageData.length > 0) {
          allTransactions = allTransactions.concat(pageData);
          if (pageData.length < pageSize) {
            hasMore = false;
          } else {
            page++;
          }
        } else {
          hasMore = false;
        }
      }

      let categories = catsRes.data || [];
      let accounts = accsRes.data || [];
      if (tempsRes && tempsRes.data) {
        state.recurringTemplates = tempsRes.data.map(mapTemplateFromDb);
        localStorage.setItem('recurring_templates', JSON.stringify(state.recurringTemplates));
      }

      // Pre-populate standard categories in the cloud for this user if they don't have any
      if (categories.length === 0) {
        const catsToInsert = DEFAULT_CATEGORIES.map(c => ({
          name: c.name,
          type: c.type,
          icon: c.icon,
          color: c.color,
          user_id: userId,
          family_id: familyId
        }));
        try {
          const { data: newCats, error: catErr } = await state.supabaseClient.from('categories').insert(catsToInsert).select();
          if (!catErr && newCats) {
            categories = newCats;
          } else {
            console.warn('Failed to pre-populate categories:', catErr);
            categories = DEFAULT_CATEGORIES;
          }
        } catch (e) {
          console.warn('Failed to pre-populate categories catch:', e);
          categories = DEFAULT_CATEGORIES;
        }
      }

      // Pre-populate standard accounts in the cloud for this user if they don't have any
      if (accounts.length === 0) {
        const accsToInsert = DEFAULT_ACCOUNTS.map(a => ({
          name: a.name,
          type: a.type,
          balance: a.balance,
          user_id: userId,
          family_id: familyId
        }));
        try {
          const { data: newAccs, error: accErr } = await state.supabaseClient.from('accounts').insert(accsToInsert).select();
          if (!accErr && newAccs) {
            accounts = newAccs;
          } else {
            console.warn('Failed to pre-populate accounts:', accErr);
            accounts = DEFAULT_ACCOUNTS;
          }
        } catch (e) {
          console.warn('Failed to pre-populate accounts catch:', e);
          accounts = DEFAULT_ACCOUNTS;
        }
      }

      // Preserve pending local transactions that failed to sync (offline fallback),
      // so they are not lost when fresh cloud data overwrites local cache.
      const pendingLocal = getPendingLocalTransactions(JSON.parse(localStorage.getItem('offline_transactions') || '[]'));

      // 4.5. RECOVERY: Rescue local transactions that were dropped from the sync queue due to schema errors (e.g., recurring_template_id)
      const cloudIds = new Set(allTransactions.map(t => t.id));
      /*
      const toRecover = (() => {
        try {
          const cached = JSON.parse(localStorage.getItem('offline_transactions') || '[]');
          return cached.filter(t => {
            if (!t.id || String(t.id).startsWith('local_')) return false;
            if (t.user_id !== user.id) return false;
            if (cloudIds.has(t.id)) return false;
            // Only recover transactions from the last 30 days
            if (!t.created_at || new Date(t.created_at).getTime() < Date.now() - 30 * 24 * 60 * 60 * 1000) return false;
            return true;
          });
        } catch (_) {
          return [];
        }
      })();
      */

      // 4.5. RECOVERY: Disabled - was causing infinite loops and duplicate clutter
      /*
      if (toRecover.length > 0) {
        console.log(`Recovering ${toRecover.length} silently dropped transactions during loadData...`);
        const payloads = toRecover.map(t => {
          const { description, is_shared, recurring_template_id, photo_local_uri, photo_url, receipt, currency, base_currency, rate_to_base, amount_base, rate_source, fx_snapshot, rate_to_base_actual, rate_fetched_at, transfer_id, transfer_rate, ...dbPayload } = t;
          return dbPayload;
        });
        try {
          for (let i = 0; i < payloads.length; i += 50) {
            await state.supabaseClient.from('transactions').upsert(payloads.slice(i, i + 50));
          }
        } catch (recoverErr) {
          console.error("Failed to recover dropped transactions:", recoverErr);
        }
      }
      */

      // Deduplicate merged transactions (ID-based first, then content-based)
      const mergedTransactions = mergeAndDeduplicateTransactions(allTransactions, pendingLocal);
      mergedTransactions.sort(compareTransactions);
      state.transactions = mergedTransactions;
      state.categories = categories;
      deduplicateCategories();
      state.accounts = accounts;

      calculateInitialBalances();

      autoRecoverTemplatesFromHistory();

      // Link existing transactions to their recurring templates (content-key
      // backfill) so the recurring delete options appear from the transaction
      // modal even for transactions saved before recurring_template_id was kept.
      backfillRecurringTemplateIds();

      localStorage.setItem('offline_transactions', JSON.stringify(state.transactions));
      localStorage.setItem('offline_accounts', JSON.stringify(state.accounts));
      localStorage.setItem('offline_categories', JSON.stringify(state.categories));

      updateHeaderSyncIcon('synced');

      // Run automatic duplicate / corrupt category cleanup in background
      cleanDuplicateCategories().catch(e => console.warn('Automatic categories cleanup error:', e));

      // NOTE: cleanDuplicateTransactions no longer needed here since we dedup inline above.
      // It is kept available for manual/sync-triggered calls only.

      // Try to flush pending local items in background without blocking UI.
      if (pendingLocal.length > 0) {
        syncLocalTransactionsToCloud(userId, { silent: true }).catch(() => { });
      }
    } catch (err) {
      console.error('Supabase fetch failed, falling back to offline cache:', err);
      // Load from cache and show offline state (not error) so user knows data is still visible
      loadOfflineData();
      updateHeaderSyncIcon('offline');
      updateUI();
      if (err && typeof showSyncToast === 'function') {
        const errorMsg = err.message || (typeof err === 'string' ? err : JSON.stringify(err));
        showSyncToast('⚠️ Σφάλμα συγχρονισμού: ' + errorMsg, 8000);
      }
    }
  } else {
    updateHeaderSyncIcon('offline');
    loadOfflineData();
  }
}

function loadOfflineData() {
  // PRIVACY/ISOLATION: In guest mode, never load a previous account's cached
  // personal data (transactions, accounts, categories, recurring templates,
  // notes, trash, notifications). Guest mode must always start with a clean
  // slate. The cached data stays in localStorage so it is preserved for when
  // the user logs back into their own account.
  const isGuest = !!state.guestMode;

  if (isGuest) {
    state.currentUser = null;
    state.partnerProfile = null;
    state.userProfile = null;
    state.familyProfiles = [];
    state.familyGroup = null;
    state.transactions = [];
    state.accounts = DEFAULT_ACCOUNTS.slice();
    state.categories = DEFAULT_CATEGORIES.slice();
    state.recurringTemplates = [];
    state.deletedRecurringDates = [];
    state.trashTransactions = [];
    state.notifications = [];
    state.notes = [];
    calculateInitialBalances();
    return;
  }

  try {
    const cachedUser = localStorage.getItem('cached_current_user');
    if (cachedUser) {
      state.currentUser = JSON.parse(cachedUser);
    }
  } catch (e) {
    console.error('Failed to parse cached current user:', e);
  }
  try {
    const cachedPartner = localStorage.getItem('cached_partner_profile');
    if (cachedPartner) {
      state.partnerProfile = JSON.parse(cachedPartner);
    }
  } catch (e) {
    console.error('Failed to parse cached partner profile:', e);
  }
  try {
    const cachedProfile = localStorage.getItem('cached_user_profile');
    if (cachedProfile) {
      state.userProfile = JSON.parse(cachedProfile);
    }
  } catch (e) {
    console.error('Failed to parse cached user profile:', e);
  }
  try {
    const cachedFamily = localStorage.getItem('cached_family_profiles');
    state.familyProfiles = cachedFamily ? JSON.parse(cachedFamily) : [];
  } catch (e) {
    console.error('Failed to parse cached family profiles:', e);
    state.familyProfiles = [];
  }
  try {
    const cachedGroup = localStorage.getItem('cached_family_group');
    state.familyGroup = cachedGroup ? JSON.parse(cachedGroup) : null;
  } catch (e) {
    console.error('Failed to parse cached family group:', e);
    state.familyGroup = null;
  }

  try {
    const trans = localStorage.getItem('offline_transactions');
    state.transactions = trans ? JSON.parse(trans) : [];
  } catch (e) {
    console.error('Failed to parse offline transactions:', e);
    state.transactions = [];
  }
  try {
    const accs = localStorage.getItem('offline_accounts');
    state.accounts = accs ? JSON.parse(accs) : DEFAULT_ACCOUNTS;
  } catch (e) {
    console.error('Failed to parse offline accounts:', e);
    state.accounts = DEFAULT_ACCOUNTS;
  }
  try {
    const cats = localStorage.getItem('offline_categories');
    state.categories = cats ? JSON.parse(cats) : DEFAULT_CATEGORIES;
    deduplicateCategories();
  } catch (e) {
    console.error('Failed to parse offline categories:', e);
    state.categories = DEFAULT_CATEGORIES;
    deduplicateCategories();
  }

  try {
    const temps = localStorage.getItem('recurring_templates');
    state.recurringTemplates = temps ? JSON.parse(temps) : [];
  } catch (e) {
    console.error('Failed to parse recurring templates:', e);
    state.recurringTemplates = [];
  }
  try {
    const deleted = localStorage.getItem('deleted_recurring_dates');
    state.deletedRecurringDates = deleted ? JSON.parse(deleted) : [];
  } catch (e) {
    console.error('Failed to parse deleted recurring dates:', e);
    state.deletedRecurringDates = [];
  }
  try {
    const trash = localStorage.getItem('deleted_transactions_trash');
    state.trashTransactions = trash ? JSON.parse(trash) : [];
  } catch (e) {
    console.error('Failed to parse deleted transactions trash:', e);
    state.trashTransactions = [];
  }
  try {
    const notifs = localStorage.getItem('money_manager_notifications');
    state.notifications = notifs ? JSON.parse(notifs) : [];
  } catch (e) {
    console.error('Failed to parse notifications:', e);
    state.notifications = [];
  }

  loadNotes();

  autoRecoverTemplatesFromHistory();
  processRecurringTemplates();
  calculateInitialBalances();
  cleanDuplicateCategories().catch(e => console.warn('Offline automatic categories cleanup error:', e));
}




function autoRecoverTemplatesFromHistory() {
  if (localStorage.getItem('templates_autorecovered') === 'true') return;
  if (!state.transactions || state.transactions.length === 0) return;

  let dismissed = [];
  try {
    dismissed = JSON.parse(localStorage.getItem('dismissed_recovered_templates') || '[]');
  } catch (e) { }

  let updated = false;

  // 1. Auto-cleanup of bad "διάφορα συμπληρώματα" templates
  const originalLength = (state.recurringTemplates || []).length;
  state.recurringTemplates = (state.recurringTemplates || []).filter(t => {
    const note = (t.note || '').toLowerCase();
    const isBad = note.includes('συμπληρώματα') || note.includes('συμπληρωματα') || note.includes('συμπλήρωμα') || note.includes('συμπληρωμα');
    if (isBad) {
      console.log('Auto-removed bad template:', t);
      if (state.supabaseClient && state.currentUser && t.id && !String(t.id).startsWith('recovered_')) {
        state.supabaseClient
          .from('recurring_templates')
          .delete()
          .eq('id', t.id)
          .then(({ error }) => {
            if (error) console.error('Failed to delete bad template from cloud:', error);
          });
      }
    }
    return !isBad;
  });

  if ((state.recurringTemplates || []).length !== originalLength) {
    updated = true;
  }

  // Disabled auto-clear of recovered templates to prevent deleted templates/transactions from returning

  const templates = state.recurringTemplates || [];

  const hasTemplate = (keywords) => {
    return templates.some(t => {
      const noteLower = (t.note || '').toLowerCase();
      return keywords.some(kw => noteLower.includes(kw));
    });
  };

  const cleanNoteOfInstallments = (note) => {
    // Remove "δόση X/Y", "δόση X", "X/Y", "δόση", etc.
    let cleaned = note.replace(/δ[όο]ση\s+\d+\/\d+/gi, '');
    cleaned = cleaned.replace(/δ[όο]ση\s+\d+/gi, '');
    cleaned = cleaned.replace(/\d+\/\d+/g, '');
    cleaned = cleaned.replace(/δ[όο]ση/gi, '');
    // Remove extra spaces
    cleaned = cleaned.replace(/\s+/g, ' ').trim();
    return cleaned || note;
  };

  const findInstallmentEndDate = (matches) => {
    let maxCurrent = 0, maxTotal = 0, maxDate = null;
    for (const t of matches) {
      const m = (t.note || '').match(/(\d+)\/(\d+)/);
      if (m) {
        const c = parseInt(m[1]), tot = parseInt(m[2]);
        if (c > maxCurrent) {
          maxCurrent = c;
          maxTotal = tot;
          maxDate = String(t.date || '').split('T')[0];
        }
      }
    }
    if (maxDate && maxTotal > 0) {
      const remaining = maxTotal - maxCurrent;
      const d = new Date(maxDate);

      // Move to the 1st of the month first to avoid month rollover bugs (e.g. Feb 30th)
      d.setDate(1);
      d.setMonth(d.getMonth() + remaining);

      // Set to the last day of that target month to cover all days of that last installment month
      const lastDay = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
      d.setDate(lastDay);

      return d.toISOString().split('T')[0];
    }
    return null; // No installment pattern found → perpetual
  };

  const recoverForKeywords = (keywords, defaultNote, preset = 'monthly') => {
    // Check if any dismissed note matches this template's defaultNote or contains its keywords
    const isDismissed = dismissed.some(dn => {
      const dnLower = String(dn || '').toLowerCase();
      return dnLower === defaultNote.toLowerCase() || keywords.some(kw => dnLower.includes(kw.toLowerCase()));
    });
    if (isDismissed) {
      console.log('[AutoRecover] Skipping recovery for:', defaultNote, 'as it is in the dismissed list');
      return;
    }
    if (hasTemplate(keywords)) return;

    const matches = state.transactions.filter(t => {
      const noteLower = (t.note || '').toLowerCase();
      return keywords.some(kw => noteLower.includes(kw));
    });
    if (matches.length === 0) return;

    // Prioritize transactions that have installment indicators (e.g. X/Y, "δόση")
    // to avoid recovering large one-off bulk payments (like a total annual ENFIA of 273.01€)
    let targetMatches = matches;
    const installmentMatches = matches.filter(t => {
      const noteLower = (t.note || '').toLowerCase();
      return noteLower.match(/\d+\/\d+/) || noteLower.includes('δόση') || noteLower.includes('δοση');
    });
    if (installmentMatches.length > 0) {
      targetMatches = installmentMatches;
    }

    // For end date, use all relevant matches; for the template base use the earliest transaction (startDate)
    const sortedAsc = [...targetMatches].sort((a, b) => new Date(a.date) - new Date(b.date));
    const tx = sortedAsc[0]; // Earliest transaction = true startDate

    const cleanedNote = defaultNote === 'ΔΟΣΗ ΔΑΝΕΙΟΥ' ? 'ΔΟΣΗ ΔΑΝΕΙΟΥ' : cleanNoteOfInstallments(tx.note || defaultNote);
    const detectedEndDate = findInstallmentEndDate(targetMatches);

    const template = {
      id: generateUUID(),
      amount: parseFloat(tx.amount),
      type: tx.type,
      category: tx.category,
      subcategory: tx.subcategory || '',
      account_from: tx.account_from,
      account_to: tx.account_to || null,
      note: cleanedNote,
      description: tx.description || '',
      preset: preset,
      days: [new Date(tx.date).getDate()],
      months: preset === 'yearly' ? [new Date(tx.date).getMonth() + 1] : [],
      years: [],
      endType: detectedEndDate ? 'date' : 'perpetual',
      endDate: detectedEndDate || null,
      startDate: tx.date,
      startYear: new Date(tx.date).getFullYear(),
      startMonth: new Date(tx.date).getMonth() + 1,
      user_id: tx.user_id || (state.currentUser ? state.currentUser.id : null),
      family_id: tx.family_id || (state.userProfile ? state.userProfile.family_id : null),
      is_shared: tx.family_id ? true : false
    };

    state.recurringTemplates.push(template);
    console.log('Auto-recovered template for keywords ' + keywords.join('/') + ':', template);

    if (state.supabaseClient && state.currentUser) {
      state.supabaseClient
        .from('recurring_templates')
        .insert([mapTemplateToDb(template)])
        .then(({ error }) => {
          if (error) console.error('Failed to save auto-recovered template to Supabase:', error);
        });
    }
    updated = true;
  };

  // 1. Car insurance (Yearly)
  const insuranceKeywords = ['ασφάλεια', 'ασφαλεια', 'ετησια ασφ', 'ετήσια ασφ', 'asfaleia', 'ασφάλιστρα', 'ασφαλιστρα', 'insurance'];
  recoverForKeywords(insuranceKeywords, 'Ετήσια Ασφάλεια Αυτοκινήτου', 'monthly');

  // 2. Home loan (Monthly) - Only match 'δόση δανείου' exactly to prevent matching general loan transactions
  const loanKeywords = ['δόση δανείου', 'δοση δανειου', 'δωση δανειου'];
  recoverForKeywords(loanKeywords, 'ΔΟΣΗ ΔΑΝΕΙΟΥ', 'monthly');

  // 3. Tires change (Yearly)
  const tiresKeywords = ['ελαστικά', 'ελαστικα', 'ελαστικων', 'ελαστικω', 'ελαστικ', 'λάστιχα', 'λαστιχα', 'λαστιχο', 'tires', 'tyres'];
  recoverForKeywords(tiresKeywords, 'Αλλαγή Ελαστικών', 'monthly');

  // 4. ENFIA (Monthly)
  const enfiaKeywords = ['ενφια', 'enfia'];
  recoverForKeywords(enfiaKeywords, 'ΕΝΦΙΑ', 'monthly');

  if (updated) {
    localStorage.setItem('recurring_templates', JSON.stringify(state.recurringTemplates));
    updateUI();
  }

  // Broad automatic cleanup of duplicate/stranded templates and transactions
  if (state.transactions && state.transactions.length > 0) {
    let anyChanges = false;
    const idsToDelete = [];

    // A. Clean up templates from recurringTemplates & Supabase
    const templatesToDelete = (state.recurringTemplates || []).filter(t => {
      const note = (t.note || '').toUpperCase();
      const amt = parseFloat(t.amount) || 0;
      return note.includes('ΔΑΝΕΙΟ ΣΠΙΤΙΩΝ') || note.includes('ΕΝΦΙΑ 2025') || Math.abs(amt - 273.01) < 0.01;
    });

    if (templatesToDelete.length > 0) {
      const templateIds = templatesToDelete.map(t => t.id);
      console.log('[Cleanup] Found bad templates in state, removing:', templateIds);
      state.recurringTemplates = (state.recurringTemplates || []).filter(t => !templateIds.includes(t.id));
      localStorage.setItem('recurring_templates', JSON.stringify(state.recurringTemplates));
      anyChanges = true;

      if (state.supabaseClient && state.currentUser) {
        state.supabaseClient
          .from('recurring_templates')
          .delete()
          .in('id', templateIds)
          .then(({ error }) => {
            if (error) console.error('[Cleanup] Failed to delete templates from cloud:', error);
            else console.log('[Cleanup] Successfully deleted bad templates from cloud');
          });
      }
    }

    // B. Clean up transactions for ΔΑΝΕΙΟ ΣΠΙΤΙΟΥ +120 ΑΣΦΑΛΕΙΑ (644.92€)
    const match644 = state.transactions.filter(t => {
      const note = (t.note || '').toUpperCase();
      const amt = parseFloat(t.amount) || 0;
      return (note.includes('ΔΑΝΕΙΟ') && note.includes('ΑΣΦΑΛΕΙΑ')) || Math.abs(amt - 644.92) < 0.01;
    });
    if (match644.length > 1) {
      match644.sort((a, b) => new Date(a.date) - new Date(b.date));
      const duplicates = match644.slice(1);
      duplicates.forEach(d => idsToDelete.push(d.id));
      console.log('[Cleanup] Found', match644.length, '644.92€ transactions. Keeping original from:', match644[0].date);
    }

    // C. Clean up transactions for ΔΑΝΕΙΟ ΣΠΙΤΙΩΝ (524.38€)
    const match524 = state.transactions.filter(t => {
      const note = (t.note || '').toUpperCase();
      return note.includes('ΔΑΝΕΙΟ ΣΠΙΤΙΩΝ');
    });
    if (match524.length > 1) {
      match524.sort((a, b) => new Date(a.date) - new Date(b.date));
      const duplicates = match524.slice(1);
      duplicates.forEach(d => idsToDelete.push(d.id));
      console.log('[Cleanup] Found', match524.length, 'ΔΑΝΕΙΟ ΣΠΙΤΙΩΝ transactions. Keeping original from:', match524[0].date);
    }

    // D. Clean up transactions for ΕΝΦΙΑ 2025 (273.01€)
    const match273 = state.transactions.filter(t => {
      const note = (t.note || '').toUpperCase();
      const amt = parseFloat(t.amount) || 0;
      return note.includes('ΕΝΦΙΑ 2025') || Math.abs(amt - 273.01) < 0.01;
    });
    if (match273.length > 1) {
      match273.sort((a, b) => new Date(a.date) - new Date(b.date));
      const duplicates = match273.slice(1);
      duplicates.forEach(d => idsToDelete.push(d.id));
      console.log('[Cleanup] Found', match273.length, 'ENFIA 273.01€ transactions. Keeping original from:', match273[0].date);
    }

    if (idsToDelete.length > 0) {
      state.transactions = state.transactions.filter(t => !idsToDelete.includes(t.id));
      localStorage.setItem('offline_transactions', JSON.stringify(state.transactions));
      anyChanges = true;

      if (state.supabaseClient && state.currentUser) {
        state.supabaseClient
          .from('transactions')
          .delete()
          .in('id', idsToDelete)
          .then(({ error }) => {
            if (error) console.error('[Cleanup] Failed to delete cloud transactions:', error);
            else console.log('[Cleanup] Successfully deleted duplicate transactions from cloud');
          });
      }
    }

    if (anyChanges) {
      setTimeout(() => {
        calculateInitialBalances();
        updateUI();
      }, 100);
    }
  }
  localStorage.setItem('templates_autorecovered', 'true');
}

function getDeletedDatesFromTemplate(template) {
  if (!template) return [];
  const desc = template.description || '';
  const match = desc.match(/\|\|deleted_dates:([^\s]+)/);
  if (match) {
    return match[1].split(',').filter(d => d);
  }
  return [];
}

function addDeletedDateToTemplate(template, dateString) {
  if (!template) return;
  const currentDates = getDeletedDatesFromTemplate(template);
  if (!currentDates.includes(dateString)) {
    currentDates.push(dateString);
  }
  let cleanDesc = (template.description || '').split('||deleted_dates:')[0].trim();
  template.description = `${cleanDesc} ||deleted_dates:${currentDates.join(',')}`.trim();
}

function processRecurringTemplates() {
  if (!state.recurringTemplates || state.recurringTemplates.length === 0) return;

  let transactionsUpdated = false;
  const currentYear = state.selectedYear;

  const today = new Date();
  const realYear = today.getFullYear();
  const realMonth = today.getMonth(); // 0-indexed

  // Limit processing to 12 months in the future from today's real month
  const maxFutureDate = new Date(realYear, realMonth + 12, 1);
  const maxFutureYear = maxFutureDate.getFullYear();
  const maxFutureMonth = maxFutureDate.getMonth();

  // If the user is browsing beyond 12 months in the future, do not process
  if (currentYear > maxFutureYear) return;
  if (currentYear === maxFutureYear && state.selectedMonth > maxFutureMonth) return;

  // For past years: process all months normally (0–11).
  // For current and safe future years: process up to the selected/viewed month.
  const currentMonthLimit = (currentYear < realYear)
    ? 11
    : state.selectedMonth;

  // Helper to get matching dates for a specific month
  function getRecurringDatesForMonth(template, year, monthIdx) {
    const dates = [];
    const monthNum = monthIdx + 1;

    const startDateStr = template.startDate || `${template.startYear || year}-${String(template.startMonth || 1).padStart(2, '0')}-01`;
    const startDate = new Date(startDateStr);
    const startYear = startDate.getFullYear();
    const startMonth = startDate.getMonth() + 1;
    const startDay = startDate.getDate();

    if (year < startYear) return dates;
    if (year === startYear && monthNum < startMonth) return dates;

    if (template.years && template.years.length > 0) {
      if (!template.years.includes(year)) return dates;
    }

    const preset = template.preset || 'custom';
    const lastDay = new Date(year, monthIdx + 1, 0).getDate();

    if (preset === 'daily') {
      for (let d = 1; d <= lastDay; d++) {
        if (year === startYear && monthNum === startMonth && d < startDay) continue;
        dates.push(`${year}-${String(monthNum).padStart(2, '0')}-${String(d).padStart(2, '0')}`);
      }
    } else if (preset === 'weekly') {
      const targetDayOfWeek = startDate.getDay();
      for (let d = 1; d <= lastDay; d++) {
        const dObj = new Date(year, monthIdx, d);
        if (dObj.getDay() === targetDayOfWeek) {
          if (year === startYear && monthNum === startMonth && d < startDay) continue;
          dates.push(`${year}-${String(monthNum).padStart(2, '0')}-${String(d).padStart(2, '0')}`);
        }
      }
    } else if (preset === 'monthly') {
      const day = Math.min(startDay, lastDay);
      if (!(year === startYear && monthNum === startMonth && day < startDay)) {
        dates.push(`${year}-${String(monthNum).padStart(2, '0')}-${String(day).padStart(2, '0')}`);
      }
    } else if (preset === 'yearly') {
      if (monthNum === startMonth) {
        const day = Math.min(startDay, lastDay);
        dates.push(`${year}-${String(monthNum).padStart(2, '0')}-${String(day).padStart(2, '0')}`);
      }
    } else if (preset === 'specific_months') {
      if (template.months && template.months.includes(monthNum)) {
        const day = Math.min(startDay, lastDay);
        if (!(year === startYear && monthNum === startMonth && day < startDay)) {
          dates.push(`${year}-${String(monthNum).padStart(2, '0')}-${String(day).padStart(2, '0')}`);
        }
      }
    } else if (preset === 'custom') {
      if (template.months && template.months.includes(monthNum)) {
        if (template.days) {
          template.days.forEach(day => {
            if (day <= lastDay) {
              if (year === startYear && monthNum === startMonth && day < startDay) return;
              dates.push(`${year}-${String(monthNum).padStart(2, '0')}-${String(day).padStart(2, '0')}`);
            }
          });
        }
      }
    }

    if (template.endDate) {
      return dates.filter(dStr => dStr <= template.endDate);
    }

    return dates;
  }

  state.recurringTemplates.forEach(template => {
    const preset = template.preset || 'custom';
    if (preset === 'custom' && (!template.days || !template.months || template.days.length === 0 || template.months.length === 0)) {
      return;
    }
    if (preset === 'specific_months' && (!template.months || template.months.length === 0)) {
      return;
    }

    for (let m = 0; m <= currentMonthLimit; m++) {
      const datesToProcess = getRecurringDatesForMonth(template, currentYear, m);

      datesToProcess.forEach(dateString => {
        const deleteKey = `${template.id}_${dateString}`;

        if ((state.deletedRecurringDates && state.deletedRecurringDates.includes(deleteKey)) ||
          getDeletedDatesFromTemplate(template).includes(dateString)) {
          return;
        }

        // Check for duplicates by BOTH recurring_template_id (if stored) AND by content-key.
        // The content-key fallback is critical because the recurring_template_id column may not
        // exist in the database, so fetched transactions arrive with recurring_template_id=null,
        // causing false negatives in the ID-only check and infinite re-creation loops.
        const duplicateExists = state.transactions.some(t => {
          const tDate = String(t.date || '').split('T')[0].split(' ')[0];
          if (t.recurring_template_id && t.recurring_template_id === template.id && tDate === dateString) {
            return true;
          }
          // Content-based fallback: same date + amount + type + category + account_from
          if (tDate === dateString &&
            (parseFloat(t.amount) || 0).toFixed(2) === (parseFloat(template.amount) || 0).toFixed(2) &&
            t.type === template.type &&
            t.category === template.category &&
            (t.account_from || '') === (template.account_from || '')) {
            return true;
          }
          return false;
        });

        if (!duplicateExists) {
          const newTx = {
            id: generateUUID(),
            recurring_template_id: template.id,
            date: dateString,
            type: template.type,
            amount: parseFloat(template.amount),
            category: (() => {
              // Normalize a ghost template category (e.g. "Αυτοκίνητο") to its
              // canonical stored name (e.g. "🚗 ΑΥΤΟΚΙΝΗΤΟ") so generated
              // transactions don't carry a phantom category with a wrong icon.
              const rawCat = template.category;
              if (!rawCat) return rawCat;
              const normCat = normalizeCategoryName(rawCat);
              if (normCat) {
                const canonical = state.categories.find(c => c.name && normalizeCategoryName(c.name) === normCat);
                if (canonical) return canonical.name;
              }
              return rawCat;
            })(),
            subcategory: template.subcategory || '',
            account_from: template.account_from,
            account_to: template.type === 'transfer' ? template.account_to : null,
            note: template.note,
            description: template.description || '',
            user_id: template.user_id || (state.currentUser ? state.currentUser.id : null),
            is_shared: template.is_shared !== undefined ? template.is_shared : (state.partnerProfile !== null),
            family_id: template.family_id || (state.userProfile ? state.userProfile.family_id : null),
            created_at: new Date().toISOString()
          };

          saveTransactionOffline(newTx);

          if (state.isSupabaseEnabled && state.supabaseClient && state.currentUser) {
            const { description, is_shared, photo_local_uri, photo_url, receipt, currency, base_currency, rate_to_base, amount_base, rate_source, fx_snapshot, rate_to_base_actual, rate_fetched_at, transfer_id, transfer_rate, ...dbPayload } = newTx;
            (async () => {
              try {
                const { error } = await promiseTimeout(
                  state.supabaseClient
                    .from('transactions')
                    .upsert([dbPayload]),
                  12000
                );
                if (error) throw error;
                console.log(`Cloud sync success for recurring transaction: ${newTx.id}`);
              } catch (err) {
                console.warn(`Cloud save failed for recurring, queueing transaction: ${newTx.id}`, err);
                enqueueSyncMutation('save', newTx);
              }
            })();
          }

          transactionsUpdated = true;
        }
      });
    }
  });

  if (transactionsUpdated) {
    calculateInitialBalances();
  }
}

// ============================================================
// SAVE / DELETE
// ============================================================
// HIGH-EXPENSE ALERT (Υψηλή Δαπάνη)
// The "Single Expense Alert" setting was previously a UI-only stub:
// the settings (settings_expense_alert_enabled / _limit) were saved to
// localStorage but NO code ever checked them or fired a notification.
// This helper wires the setting to the actual alert. It is called from
// saveTransaction() so it fires for ANY expense added (form, coach, demo).
// ============================================================
function checkHighExpenseAlert(transaction) {
  try {
    // Only expenses (not income/transfers) can trigger the high-expense alert.
    if (!transaction || transaction.type !== 'expense') return;

    const enabled = localStorage.getItem('settings_expense_alert_enabled') === 'true';
    if (!enabled) return;

    const limit = parseFloat(localStorage.getItem('settings_expense_alert_limit')) || 500;
    const amount = parseFloat(transaction.amount) || 0;
    if (amount < limit) return;

    const catName = getCategoryDisplayName ? getCategoryDisplayName(transaction.category) : (transaction.category || '');
    const title = state.lang === 'el' ? '⚠️ Υψηλή Δαπάνη' : '⚠️ High Expense Alert';
    const body = state.lang === 'el'
      ? `Καταχωρήθηκε δαπάνη ${formatCurrency(amount)} (${catName}) που υπερβαίνει το όριο των ${formatCurrency(limit)}.`
      : `An expense of ${formatCurrency(amount)} (${catName}) was recorded, exceeding your limit of ${formatCurrency(limit)}.`;

    // 1. In-app notification (notification center / badge)
    addInAppNotification(title, body, { type: 'open_transactions' });

    // 2. Toast so the user sees it immediately
    if (typeof showToast === 'function') {
      showToast(title + ' — ' + body, 'warning');
    }

    // 3. Native push-style notification (works when app is in background)
    if (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.LocalNotifications) {
      const LocalNotifications = window.Capacitor.Plugins.LocalNotifications;
      LocalNotifications.schedule({
        notifications: [{
          id: 9000 + (Math.floor(Math.random() * 900) + 100),
          title: title,
          body: body,
          schedule: { at: new Date(Date.now() + 500) },
          sound: null,
          attachments: null,
          actionTypeId: '',
          extra: { type: 'high_expense' }
        }]
      }).catch(err => console.warn('Failed to schedule high-expense native notification:', err));
    }

    console.log(`[ALERT] High expense detected: ${amount} >= ${limit}`);
  } catch (err) {
    // Never let a notification failure break the transaction save.
    console.warn('checkHighExpenseAlert error:', err);
  }
}

async function saveTransaction(transaction) {
  transaction.amount = parseFloat(transaction.amount);

  // HIGH-EXPENSE ALERT: Fire the "Single Expense Alert" notification if this
  // newly saved expense meets/exceeds the configured limit (settings_expense_alert_limit).
  checkHighExpenseAlert(transaction);

  // 1. Generate local UUID if it's a new transaction
  if (!transaction.id) {
    transaction.id = generateUUID();
  }

  // Populate user_id and family_id before saving offline to prevent guest sync duplication
  if (state.isSupabaseEnabled && state.supabaseClient && state.currentUser) {
    if (!transaction.user_id) {
      transaction.user_id = state.currentUser.id;
    }
    if (!transaction.family_id && state.userProfile && state.userProfile.family_id) {
      transaction.family_id = state.userProfile.family_id;
    }
  }

  // 2. Optimistically save to local state and local storage immediately
  saveTransactionOffline(transaction);
  // Guard against the re-fetch race: keep this transaction in the "recently saved"
  // set so a loadData() re-fetch that hasn't yet seen the cloud write does NOT drop it.
  _markRecentlySaved(transaction.id);
  calculateInitialBalances();
  updateUI();

  // 3. Attempt to save to cloud in background
  if (state.isSupabaseEnabled && state.supabaseClient && state.currentUser) {

    // Note: description and is_shared are client-only fields that do NOT exist as
    // columns in the transactions table (verified live: error 42703), so they MUST
    // be stripped here or the upsert fails with a 400. recurring_template_id DOES
    // exist as a column, so it is intentionally KEPT so cloud-loaded transactions
    // retain their link to the recurring template (fixes recurring delete options
    // not appearing from the transaction modal in the APK).
    const { description, is_shared, photo_local_uri, photo_url, receipt, currency, base_currency, rate_to_base, amount_base, rate_source, fx_snapshot, rate_to_base_actual, rate_fetched_at, transfer_id, transfer_rate, ...dbPayload } = transaction;

    // Enqueue immediately before starting the cloud request to prevent data loss if the app is closed/killed
    enqueueSyncMutation('save', transaction);

    (async () => {
      try {
        // Suppress realtime echo of our own upsert to prevent a second UI render ~5s after save.
        _suppressRealtimeEvents = true;
        const { error } = await promiseTimeout(
          state.supabaseClient
            .from('transactions')
            .upsert([dbPayload]),
          12000
        );
        if (error) throw error;
        console.log(`Cloud sync success for transaction: ${transaction.id}`);
        dequeueSyncMutation('save', transaction.id);
      } catch (err) {
        console.warn(`Cloud save failed, keeping in queue: ${transaction.id}`, err);
      } finally {
        // Re-enable realtime after enough time for the echo to arrive and be discarded.
        setTimeout(() => { _suppressRealtimeEvents = false; }, 8000);
      }
    })();
  }
}

function saveTransactionOffline(transaction) {
  if (!transaction.id) {
    transaction.id = generateUUID();
  }
  if (!transaction.created_at) {
    transaction.created_at = new Date().toISOString();
  }
  let trans = [...state.transactions];
  const existingIdx = trans.findIndex(t => t.id === transaction.id);
  if (existingIdx !== -1) {
    const oldTx = trans[existingIdx];
    const oldDate = String(oldTx.date || '').split('T')[0].split(' ')[0];
    const newDate = String(transaction.date || '').split('T')[0].split(' ')[0];

    // If it's a recurring transaction and the date changed, mark the old date as deleted
    // so the generator doesn't recreate it on the old date.
    if (oldDate !== newDate && oldTx.recurring_template_id) {
      const key = `${oldTx.recurring_template_id}_${oldDate}`;
      if (!state.deletedRecurringDates.includes(key)) {
        state.deletedRecurringDates.push(key);
        localStorage.setItem('deleted_recurring_dates', JSON.stringify(state.deletedRecurringDates));
      }
    }

    trans[existingIdx] = transaction;
  } else {
    trans.unshift(transaction);
  }
  state.transactions = trans;
  localStorage.setItem('offline_transactions', JSON.stringify(trans));
}

function deleteTransaction(id) {
  if (!id) return;

  // Delete only the transaction with this unique id.
  // Content-based "duplicate" matching was removed because it could delete
  // legitimate identical transactions (same date/amount/category/note).
  const idsToDelete = [String(id)];

  // 1. Mark all these IDs as deleting
  idsToDelete.forEach(dId => _deletingTxIds.add(dId));

  // 2. Clean up local receipt photo from IndexedDB (run in background)
  idsToDelete.forEach(dId => {
    ReceiptStorage.remove(dId).catch(err => {
      console.warn('Failed to remove receipt during transaction delete:', err);
    });
  });

  // Save deleted transactions to Trash
  try {
    const deletedTxs = state.transactions.filter(t => idsToDelete.includes(String(t.id)));
    deletedTxs.forEach(t => {
      state.trashTransactions = state.trashTransactions || [];
      const alreadyInTrash = state.trashTransactions.some(tt => String(tt.id) === String(t.id));
      if (!alreadyInTrash) {
        const trashItem = { ...t, deleted_at: new Date().toISOString() };
        state.trashTransactions.push(trashItem);
      }
    });
    if (state.trashTransactions.length > 100) {
      state.trashTransactions = state.trashTransactions.slice(-100);
    }
    localStorage.setItem('deleted_transactions_trash', JSON.stringify(state.trashTransactions));
  } catch (err) {
    console.warn('Failed to save deleted transactions to trash:', err);
  }

  // 3. Optimistically delete from local state and update UI
  idsToDelete.forEach(dId => deleteTransactionOffline(dId, true));
  localStorage.setItem('offline_transactions', JSON.stringify(state.transactions));
  calculateInitialBalances();
  updateUI();

  // 4. Perform background delete (status model: soft-delete via status='deleted')
  if (state.isSupabaseEnabled && state.supabaseClient && state.currentUser) {
    // Enqueue immediately before starting the cloud request to prevent data loss if the app is closed/killed
    idsToDelete.forEach(dId => enqueueSyncMutation('delete', dId));

    (async () => {
      try {
        _suppressRealtimeEvents = true;
        // Instead of hard-deleting, mark the transaction as deleted so it can be
        // restored from the trash and stays consistent across all devices.
        const { error } = await promiseTimeout(
          state.supabaseClient
            .from('transactions')
            .update({
              status: 'deleted',
              deleted_at: new Date().toISOString(),
              deleted_by: state.currentUser.id
            })
            .in('id', idsToDelete),
          12000
        );
        if (error) throw error;
        console.log(`Cloud soft-delete success for transaction:`, idsToDelete);
        // Keep IDs in _recentlyDeletedTxIds for 30s to guard against Supabase propagation race:
        // loadData() may run shortly after and re-fetch the transaction before the DB confirms the delete.
        idsToDelete.forEach(dId => _markRecentlyDeleted(dId));
        idsToDelete.forEach(dId => dequeueSyncMutation('delete', dId));
      } catch (err) {
        console.warn(`Cloud delete failed, keeping in queue:`, idsToDelete, err);
      } finally {
        idsToDelete.forEach(dId => _deletingTxIds.delete(dId));
        setTimeout(() => { _suppressRealtimeEvents = false; }, 8000);
      }
    })();
  } else {
    idsToDelete.forEach(dId => _deletingTxIds.delete(dId));
  }
}

function deleteTransactionOffline(id, skipSave = false) {
  const tx = state.transactions.find(t => t.id === id);
  if (tx) {
    let templateId = tx.recurring_template_id;
    const txDate = String(tx.date || '').split('T')[0].split(' ')[0];

    if (!templateId && state.recurringTemplates) {
      // Find template matching by content if recurring_template_id is missing
      const match = state.recurringTemplates.find(template => {
        return (parseFloat(tx.amount) || 0).toFixed(2) === (parseFloat(template.amount) || 0).toFixed(2) &&
          tx.type === template.type &&
          tx.category === template.category &&
          (tx.account_from || '') === (template.account_from || '');
      });
      if (match) {
        templateId = match.id;
      }
    }

    if (templateId) {
      const key = `${templateId}_${txDate}`;
      if (!state.deletedRecurringDates.includes(key)) {
        state.deletedRecurringDates.push(key);
        localStorage.setItem('deleted_recurring_dates', JSON.stringify(state.deletedRecurringDates));
      }
      const template = state.recurringTemplates.find(t => t.id === templateId);
      if (template) {
        addDeletedDateToTemplate(template, txDate);
        localStorage.setItem('recurring_templates', JSON.stringify(state.recurringTemplates));
        if (state.supabaseClient && state.currentUser) {
          enqueueSyncMutation('save_template', template);
          state.supabaseClient
            .from('recurring_templates')
            .upsert([mapTemplateToDb(template)])
            .then(({ error }) => {
              if (!error) {
                dequeueSyncMutation('save_template', template.id);
              }
            });
        }
      }
    }
  }
  // Remove only the transaction with this unique id.
  // Content-based "duplicate" removal was removed because it could delete
  // legitimate identical transactions (same date/amount/category/note).
  state.transactions = state.transactions.filter(t => t.id !== id);
  if (!skipSave) {
    localStorage.setItem('offline_transactions', JSON.stringify(state.transactions));
  }
}

// ============================================================
// UI UPDATE ENGINE
// ============================================================

// ============================================================
// FIX #4 (flicker): Central render scheduler.
// All UI renders funnel through updateUI() which coalesces bursts
// into a single pass. Key improvements over the old scheduler:
//   1. A single updateUI() call flushes on the NEXT animation frame
//      (no artificial 150ms latency for isolated renders).
//   2. A burst of updateUI() calls within the debounce window collapses
//      into ONE render (no more 32+ concurrent DOM mutations racing).
//   3. flushUI() cancels any pending scheduled render and renders
//      immediately — used by switchTab so a tab switch never races
//      against a background-sync render.
// ============================================================
let _updateUITimer = null;
let _updateUIRAF = null;
let _updateUIDirty = false;

function _runScheduledRender() {
  _updateUITimer = null;
  _updateUIRAF = null;
  _updateUIDirty = false;
  // ANTI-FLICKER: When _suppressTransitions is set (e.g. during the
  // startup loadData() re-render after a long background where the OS
  // reloaded the WebView), wrap the DOM wipe/re-render in no-transition
  // so the tab content does not visibly flash. This covers the full-reload
  // path that forceSyncNow's own guard cannot reach.
  const suppress = !!window._suppressTransitions;
  if (suppress) document.documentElement.classList.add('no-transition');
  try {
    _updateUIImpl();
  } finally {
    if (suppress) {
      setTimeout(() => {
        document.documentElement.classList.remove('no-transition');
      }, 1000);
    }
  }
}

function updateUI() {
  // If a render is already scheduled (either the resume-delay timer or the
  // pending animation-frame), just mark it dirty and let the existing
  // scheduled pass handle it — coalescing bursts into a single render.
  if (_updateUITimer || _updateUIRAF) {
    _updateUIDirty = true;
    return;
  }
  _updateUIDirty = true;

  // ANTI-FLICKER: If the app just resumed from background, defer rendering
  // until after the 600ms resume guard window expires. This prevents the
  // DOM wipe from being visible during the resume animation frame.
  const baseDelay = window._appJustResumed ? 700 : 0;

  if (baseDelay > 0) {
    _updateUITimer = setTimeout(() => {
      _updateUITimer = null;
      if (_updateUIRAF) cancelAnimationFrame(_updateUIRAF);
      _updateUIRAF = requestAnimationFrame(_runScheduledRender);
    }, baseDelay);
  } else {
    // No resume guard needed: flush on the next animation frame so that
    // multiple synchronous updateUI() calls in the same tick still coalesce
    // into a single render (avoids redundant DOM wipes).
    if (_updateUIRAF) cancelAnimationFrame(_updateUIRAF);
    _updateUIRAF = requestAnimationFrame(_runScheduledRender);
  }
}

// Immediately cancel any pending scheduled render and run the render NOW.
// Used by switchTab() so a tab switch never races against a queued
// background-sync render (which would cause a visible flash/jitter).
function flushUI() {
  if (_updateUITimer) {
    clearTimeout(_updateUITimer);
    _updateUITimer = null;
  }
  if (_updateUIRAF) {
    cancelAnimationFrame(_updateUIRAF);
    _updateUIRAF = null;
  }
  _updateUIDirty = false;
  _runScheduledRender();
}

function getActiveScrollContainer() {
  if (state.activeTab === 'trans') return document.querySelector('.trans-scroll-content');
  if (state.activeTab === 'stats') return document.querySelector('.stats-scroll-content');
  if (state.activeTab === 'accounts') return document.querySelector('.accounts-scroll-content');
  if (state.activeTab === 'more') return document.querySelector('.more-scroll-content');
  return null;
}

function _updateUIImpl() {
  processRecurringTemplates();
  updateHeaderAndSync();

  const countEl = document.getElementById('recurring-templates-count-val');
  if (countEl) {
    countEl.textContent = state.recurringTemplates ? state.recurringTemplates.length : 0;
  }
  const trashCount = state.trashTransactions ? state.trashTransactions.length : 0;
  // Update both the legacy ID and the actual badge ID used in index.html (hub-trash-count)
  const trashCountEl = document.getElementById('trash-bin-count-val');
  if (trashCountEl) {
    trashCountEl.textContent = trashCount;
  }
  const hubTrashCountEl = document.getElementById('hub-trash-count');
  if (hubTrashCountEl) {
    hubTrashCountEl.textContent = trashCount;
  }

  // Save current month/year to localStorage so they are preserved on app resume/reload
  localStorage.setItem('selected_month', state.selectedMonth);
  localStorage.setItem('selected_year', state.selectedYear);

  // If ANY modal is currently open, skip the full tab re-render.
  // A background sync (forceSyncNow) firing while a modal is visible would otherwise
  // cause the tab content behind the modal to flash/reload — visible and jarring on Android.
  // The re-render will happen naturally the next time the user closes the modal (closeModal
  // calls updateUI) or switches tabs.
  const anyModalOpen = !!document.querySelector(
    '.modal-overlay.active, .tx-modal-overlay.active, .profile-sheet-overlay.active'
  );

  if (!anyModalOpen) {
    // Save current scroll position before rendering to prevent scroll-jump
    const scrollContainer = getActiveScrollContainer();
    const currentScrollTop = scrollContainer ? scrollContainer.scrollTop : 0;

    // Render only the active tab to optimize performance and prevent background rendering lag
    if (state.activeTab === 'trans') {
      renderTransactionsTab();
    } else if (state.activeTab === 'stats') {
      renderStatsTab();
    } else if (state.activeTab === 'accounts') {
      renderAccountsTab();
    } else if (state.activeTab === 'more') {
      renderPartnerSection();
      renderNotesList();
    }

    // Restore scroll position
    const restoredScrollContainer = getActiveScrollContainer();
    if (restoredScrollContainer) {
      const bgScrollTop = localStorage.getItem('bg_scroll_top');
      if (bgScrollTop !== null) {
        restoredScrollContainer.scrollTop = parseInt(bgScrollTop, 10);
        localStorage.removeItem('bg_scroll_top');
      } else {
        restoredScrollContainer.scrollTop = currentScrollTop;
      }
    }
  }

  // Clear category render cache on UI refresh to pick up updates
  lastRenderedCategoryType = null;

  const activeTypeBtn = document.querySelector('.type-tab-btn.active');
  const currentType = activeTypeBtn ? activeTypeBtn.getAttribute('data-type') : 'expense';

  // FIX #2: Skip rebuilding dropdowns when the transaction modal is open.
  // Rebuilding category/account dropdowns while the modal is visible causes
  // the form fields to flicker (innerHTML reset) even though the modal itself
  // is correctly open. We only need to rebuild them when the modal is closed,
  // or when it is first opened (handled inside openAddTransactionModal /
  // openEditTransactionModal via updateCategoryDropdowns/updateAccountDropdowns).
  const txModalOpen = document.getElementById('transaction-modal') &&
    document.getElementById('transaction-modal').classList.contains('active');
  if (!txModalOpen) {
    updateCategoryDropdowns(currentType);
    updateAccountDropdowns();
  }
  updateCurrencySymbols();

  // Scroll to today on startup once transactions are loaded
  const list = document.getElementById('transactions-list');
  if (!state.hasInitialScrollDone && list && list.children.length > 0) {
    state.hasInitialScrollDone = true;
    setTimeout(() => {
      scrollToToday('auto');
    }, 300);
  }

  // Onboarding auto-trigger
  const authOverlay = document.getElementById('auth-overlay');
  const isAuthVisible = authOverlay && authOverlay.style.display !== 'none';
  if (!isAuthVisible && (!state.transactions || state.transactions.length === 0) && !localStorage.getItem('onboarding_welcomed')) {
    localStorage.setItem('onboarding_welcomed', 'true');
    setTimeout(() => {
      openModal('onboarding-modal');
    }, 800);
  }
}

function updateHeaderAndSync() {
  const rawText = `${getMonthName(state.selectedMonth, true)} ${state.selectedYear}`;
  const periodEl = document.getElementById('current-period-title');
  if (periodEl) periodEl.innerHTML = wrapPeriodTitleWithSpans(rawText);
  updateHeaderProfileBadge();
  if (typeof updateSyncStatusIndicator === 'function') {
    updateSyncStatusIndicator();
  }
}

// ============================================================
// TAB 1: TRANSACTIONS
// ============================================================
// Determine whether a transaction belongs to a recurring template.
// Uses recurring_template_id when present, otherwise falls back to a
// content-key match (date + amount + type + category + account_from)
// because recurring_template_id is a client-only field stripped before
// cloud upsert, so fetched transactions arrive with it null.
function isTransactionRecurring(tx) {
  if (!tx) return false;
  const templates = state.recurringTemplates || [];
  if (templates.length === 0) return false;

  if (tx.recurring_template_id) {
    const found = templates.some(t => String(t.id) === String(tx.recurring_template_id));
    if (found) return true;
  }

  const txAmount = (parseFloat(tx.amount) || 0).toFixed(2);
  const txType = tx.type;
  const txCat = normalizeCategoryName(tx.category);

  return templates.some(template => {
    if (tx.recurring_template_id && String(tx.recurring_template_id) === String(template.id)) {
      return true;
    }
    const tAmount = (parseFloat(template.amount) || 0).toFixed(2);
    const tType = template.type;
    const tCat = normalizeCategoryName(template.category);

    if (txAmount === tAmount && txType === tType && txCat === tCat) {
      return true;
    }
    return false;
  });
}

// Resolve the recurring template a transaction belongs to, using recurring_template_id
// when present, otherwise falling back to a content-key match (amount + type + category).
// Returns the matching template object or null. Used by the transaction delete handler
// so the 3-option recurring delete modal reliably appears even when the template link
// is missing on an older cloud-loaded transaction.
function resolveRecurringTemplateForTx(tx) {
  if (!tx) return null;
  const templates = state.recurringTemplates || [];
  if (templates.length === 0) return null;

  if (tx.recurring_template_id) {
    const found = templates.find(t => String(t.id) === String(tx.recurring_template_id));
    if (found) return found;
  }

  const txAmount = (parseFloat(tx.amount) || 0).toFixed(2);
  const txType = tx.type;
  const txCat = normalizeCategoryName(tx.category);

  return templates.find(template => {
    if (tx.recurring_template_id && String(tx.recurring_template_id) === String(template.id)) return true;
    const tAmount = (parseFloat(template.amount) || 0).toFixed(2);
    const tType = template.type;
    const tCat = normalizeCategoryName(template.category);
    return txAmount === tAmount && txType === tType && txCat === tCat;
  }) || null;
}

// Backfill recurring_template_id on existing transactions that were saved before
// the column was persisted (it was previously stripped before cloud upsert, so
// cloud-loaded transactions arrived with recurring_template_id = null). Linking
// them to their template by content-key makes isTransactionRecurring() work via
// the reliable ID check, so the 3-option recurring delete modal appears from the
// transaction modal in both web and APK.
function backfillRecurringTemplateIds() {
  const templates = state.recurringTemplates || [];
  if (templates.length === 0) return;
  const txs = state.transactions || [];
  if (txs.length === 0) return;

  const toUpdate = [];
  txs.forEach(tx => {
    if (tx.recurring_template_id) return; // already linked
    const txAmount = (parseFloat(tx.amount) || 0).toFixed(2);
    const txType = tx.type;
    const txCat = normalizeCategoryName(tx.category);
    const match = templates.find(t => {
      return (parseFloat(t.amount) || 0).toFixed(2) === txAmount &&
        t.type === txType &&
        normalizeCategoryName(t.category) === txCat;
    });
    if (match) {
      tx.recurring_template_id = match.id;
      toUpdate.push({ id: tx.id, recurring_template_id: match.id });
    }
  });

  if (toUpdate.length === 0) return;
  console.log('[backfill] Linked ' + toUpdate.length + ' transactions to recurring templates');

  // Persist the link to the cloud (only id + recurring_template_id) so it survives reloads.
  if (state.isSupabaseEnabled && state.supabaseClient && state.currentUser) {
    (async () => {
      try {
        for (let i = 0; i < toUpdate.length; i += 100) {
          const chunk = toUpdate.slice(i, i + 100);
          const { error } = await promiseTimeout(
            state.supabaseClient.from('transactions').upsert(chunk),
            15000
          );
          if (error) console.warn('[backfill] upsert error:', error);
        }
      } catch (e) {
        console.warn('[backfill] failed to persist links:', e);
      }
    })();
  }
}

function renderTransactionsTab() {
  const listContainer = document.getElementById('transactions-list');
  if (!listContainer) return;


  const monthStartDay = parseInt(localStorage.getItem('app_month_start') || '1', 10);
  let start, end;
  if (monthStartDay === 1) {
    start = new Date(state.selectedYear, state.selectedMonth, 1, 0, 0, 0, 0);
    end = new Date(state.selectedYear, state.selectedMonth + 1, 0, 23, 59, 59, 999);
  } else {
    start = new Date(state.selectedYear, state.selectedMonth, monthStartDay, 0, 0, 0, 0);
    end = new Date(state.selectedYear, state.selectedMonth + 1, monthStartDay - 1, 23, 59, 59, 999);
  }

  const startISO = `${start.getFullYear()}-${String(start.getMonth() + 1).padStart(2, '0')}-${String(start.getDate()).padStart(2, '0')}`;
  const endISO = `${end.getFullYear()}-${String(end.getMonth() + 1).padStart(2, '0')}-${String(end.getDate()).padStart(2, '0')}`;

  const walletTrans = getActiveTransactions();
  const filteredTrans = walletTrans.filter(t => {
    if (!t.date) return false;
    const tDatePart = String(t.date).split('T')[0].split(' ')[0];
    return tDatePart >= startISO && tDatePart <= endISO;
  });

  const sortedTrans = [...filteredTrans].sort(compareTransactions);

  // Aggregate directly in the display (app) currency. Each transaction is
  // converted from its own stored base_currency, so when the user changes the
  // app currency the totals correctly reflect the exchange rate (e.g. 1316 € →
  // ~1420 $) instead of just swapping the symbol.
  const displayCurrency = getDisplayCurrency();
  const monthlyIncome = CurrencyService.sumInCurrency(sortedTrans.filter(t => t.type === 'income'), displayCurrency);
  const monthlyExpense = CurrencyService.sumInCurrency(sortedTrans.filter(t => t.type === 'expense'), displayCurrency);
  const groups = {};

  sortedTrans.forEach(t => {
    const amt = CurrencyService.displayAmount(t, displayCurrency);
    const dateKey = String(t.date || '').split('T')[0].split(' ')[0];
    if (!groups[dateKey]) groups[dateKey] = { transactions: [], income: 0, expense: 0 };
    groups[dateKey].transactions.push(t);
    if (t.type === 'income') groups[dateKey].income += amt;
    else if (t.type === 'expense') groups[dateKey].expense += amt;
  });

  // The aggregated totals are already in the display currency, so pass the
  // display currency as the source to avoid a double conversion.
  document.getElementById('summary-income-val').textContent = `${getCurrencySymbol()} ${formatDisplayAmount(monthlyIncome, displayCurrency)}`;
  document.getElementById('summary-expense-val').textContent = `${getCurrencySymbol()} ${formatDisplayAmount(monthlyExpense, displayCurrency)}`;
  document.getElementById('summary-total-val').textContent = `${getCurrencySymbol()} ${formatDisplayAmount(monthlyIncome - monthlyExpense, displayCurrency)}`;

  if (sortedTrans.length === 0) {
    if (listContainer._lastRenderSignature === 'empty') return;
    listContainer._lastRenderSignature = 'empty';

    const lang = state.lang || 'el';
    const title = lang === 'el' ? 'Δεν έχετε προσθέσει κάτι ακόμα' : 'No transactions found';
    const desc = lang === 'el'
      ? 'Γράψτε το πρώτο σας έξοδο ή δοκιμάστε την εφαρμογή βάζοντας μερικά έτοιμα παραδείγματα!'
      : 'Start tracking your expenses or try the app with sample data!';
    const addBtnText = lang === 'el' ? '✍️ Γράψτε ένα έξοδο / έσοδο' : '✍️ Add Transaction';
    const demoBtnText = lang === 'el' ? '📊 Δείτε έτοιμα παραδείγματα' : '📊 Insert Demo Data';

    listContainer.innerHTML = `
      <div style="text-align:center;padding:60px 20px;color:var(--text-secondary); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 16px;">
        <div style="font-size:56px;">📅</div>
        <div style="display: flex; flex-direction: column; gap: 6px;">
          <h3 style="margin: 0; font-family: 'Outfit', sans-serif; font-size: 18px; font-weight: 800; color: var(--text-primary);">${title}</h3>
          <p style="margin: 0; font-size: 12.5px; max-width: 280px; line-height: 1.4; color: var(--text-secondary);">${desc}</p>
        </div>
        <div style="display: flex; flex-direction: column; gap: 10px; width: 100%; max-width: 240px; margin-top: 10px;">
          <button class="btn btn-primary" onclick="openModal('transaction-modal')" style="padding: 12px; font-size: 13.5px; font-weight: 700; border-radius: 12px; width: 100%;">
            ${addBtnText}
          </button>
          <button class="btn btn-secondary" onclick="onboardingAddDemoData()" style="padding: 12px; font-size: 13.5px; font-weight: 700; border-radius: 12px; width: 100%; border: 1px dashed var(--accent); color: var(--accent); background: rgba(124,106,247,0.04);">
            ${demoBtnText}
          </button>
        </div>
      </div>`;
    return;
  }

  // Anti-flicker signature check
  const accountsHash = state.accounts.map(a => `${a.id}_${a.name}_${a.balance}`).join('|');
  const categoriesHash = state.categories.map(c => `${c.id}_${c.name}_${c.icon}`).join('|');
  const renderSignature = sortedTrans.map(t => {
    return `${t.id}_${t.date}_${t.amount}_${t.category}_${t.subcategory || ''}_${t.type}_${t.note || ''}_${t.user_id || ''}_${state.selectedIds.has(t.id) ? '1' : '0'}`;
  }).join('|') + `_selMode_${state.selectionMode ? '1' : '0'}_lang_${state.lang || 'el'}_accs_${accountsHash}_cats_${categoriesHash}_curr_${displayCurrency}`;

  if (listContainer._lastRenderSignature === renderSignature) {
    return;
  }
  listContainer._lastRenderSignature = renderSignature;

  // ANTI-FLICKER: Use replaceChildren() instead of innerHTML='' + appendChild().
  // The old two-step approach (empty the container, then append the fragment)
  // left a visible empty/black gap for a frame between the two DOM mutations,
  // which appeared as a black flicker on resume/sync. replaceChildren() swaps
  // the entire content in ONE atomic DOM mutation, so the browser never paints
  // the empty intermediate state.
  const todayObj = new Date();
  const todayStr = `${todayObj.getFullYear()}-${String(todayObj.getMonth() + 1).padStart(2, '0')}-${String(todayObj.getDate()).padStart(2, '0')}`;

  const fragment = document.createDocumentFragment();

  Object.keys(groups).sort((a, b) => b.localeCompare(a)).forEach(dateStr => {
    const group = groups[dateStr];
    const [y, m, d] = dateStr.split('-').map(Number);
    const dateObj = new Date(y, m - 1, d);
    const dayOfWeek = dateObj.getDay();
    const dayNum = d;
    const shortDay = getWeekdayName(dayOfWeek);
    const weekendClass = dayOfWeek === 6 ? ' saturday' : dayOfWeek === 0 ? ' sunday' : '';
    const isToday = (dateStr === todayStr);

    let rightTotals = '';
    if (group.income > 0) rightTotals += `<span class="day-group-income">${getCurrencySymbol()} ${formatDisplayAmount(group.income, displayCurrency)}</span>`;
    if (group.expense > 0) rightTotals += `<span class="day-group-expense">${getCurrencySymbol()} ${formatDisplayAmount(group.expense, displayCurrency)}</span>`;

    const header = document.createElement('div');
    header.className = 'day-header' + (isToday ? ' is-today' : '');
    const todayBadge = isToday ? ` <span class="today-badge">${state.lang === 'el' ? 'ΣΗΜΕΡΑ' : 'TODAY'}</span>` : '';
    header.innerHTML = `
      <div class="day-header-left">
        <span class="day-num">${dayNum}</span>
        <div>
          <span class="day-name${weekendClass}">${shortDay}</span>${todayBadge}
          <span class="day-month">${getMonthName(m - 1, true)} ${y}</span>
        </div>
      </div>
      <div class="day-header-right">${rightTotals}</div>`;
    fragment.appendChild(header);

    group.transactions.forEach(t => {
      const catInfo = getCategoryInfo(t.category, t.type);
      const item = document.createElement('div');
      item.className = 'transaction-item';
      item.setAttribute('data-id', t.id);

      const isSelected = state.selectedIds.has(t.id);
      if (state.selectionMode && isSelected) {
        item.classList.add('selected');
      }

      const checkboxHtml = state.selectionMode ? `
        <div class="trans-checkbox ${isSelected ? 'checked' : ''}">
          <i class="fa-solid ${isSelected ? 'fa-circle-check' : 'fa-circle'}"></i>
        </div>
      ` : '';

      let pressTimer;
      let feedbackTimer;
      let isLongPress = false;

      item.addEventListener('touchstart', (e) => {
        isLongPress = false;
        state.touchDidMove = false;

        // Active visual feedback with 80ms delay to prevent flashing on swipe/scroll
        clearTimeout(feedbackTimer);
        feedbackTimer = setTimeout(() => {
          if (!state.touchDidMove && !state.isSwipingMonth) {
            item.classList.add('pressed');
          }
        }, 80);

        if (state.selectionMode) return;
        pressTimer = setTimeout(() => {
          isLongPress = true;
          enterSelectionMode();
          toggleSelection(t.id);
          if (navigator.vibrate) {
            try { navigator.vibrate(15); } catch (err) { }
          }
        }, 600);
      }, { passive: true });

      item.addEventListener('touchmove', (e) => {
        clearTimeout(pressTimer);
        clearTimeout(feedbackTimer);
        item.classList.remove('pressed');
        state.touchDidMove = true;
      }, { passive: true });

      item.addEventListener('touchend', (e) => {
        clearTimeout(pressTimer);
        clearTimeout(feedbackTimer);
        item.classList.remove('pressed');
        if (state.isSwipingMonth || state.touchDidMove) {
          if (e.cancelable) e.preventDefault();
        }
      }, { passive: false });

      item.addEventListener('touchcancel', () => {
        clearTimeout(pressTimer);
        clearTimeout(feedbackTimer);
        item.classList.remove('pressed');
      });

      item.addEventListener('mousedown', (e) => {
        isLongPress = false;
        item.classList.add('pressed');
        if (state.selectionMode) return;
        pressTimer = setTimeout(() => {
          isLongPress = true;
          enterSelectionMode();
          toggleSelection(t.id);
        }, 600);
      });
      item.addEventListener('mouseup', () => {
        clearTimeout(pressTimer);
        item.classList.remove('pressed');
      });
      item.addEventListener('mouseleave', () => {
        clearTimeout(pressTimer);
        item.classList.remove('pressed');
      });

      item.onclick = (e) => {
        if (state.isSwipingMonth || state.touchDidMove || (Date.now() - state.lastSwipeTime < 1500)) {
          isLongPress = false;
          state.touchDidMove = false;
          return;
        }
        if (isLongPress) {
          isLongPress = false;
          return;
        }
        if (state.selectionMode) {
          toggleSelection(t.id);
        } else {
          openEditTransactionModal(t);
        }
      };

      let amountClass = 'trans-amount';
      let accountText = t.account_from ? getAccountDisplayName(t.account_from) : '';
      if (t.type === 'expense') { amountClass += ' expense'; }
      else if (t.type === 'income') { amountClass += ' income'; }
      else if (t.type === 'transfer') {
        const fromDisp = getAccountDisplayName(t.account_from);
        const toDisp = getAccountDisplayName(t.account_to);
        amountClass += ' transfer';
        accountText = `${fromDisp} → ${toDisp}`;
      }

      const translatedSub = getSubcategoryDisplayName(t.subcategory, t.category);
      const translatedCat = getCategoryDisplayName(t.category);
      const displayTitle = (t.note && t.note.trim()) ? t.note.trim()
        : (t.description && t.description.trim()) ? t.description.trim()
          : (translatedSub && translatedSub.trim()) ? translatedSub.trim()
            : (translatedCat || '');

      const memberBadge = getMemberBadgeHTML(t);

      item.innerHTML = `
        ${checkboxHtml}
        <div class="trans-left">
          <div class="trans-category-container">
            <div class="trans-cat-icon">${catInfo.icon || '💰'}</div>
            <div class="trans-cat-name">${escapeHtml(translatedCat) || ''}</div>
            ${t.subcategory ? `<div class="trans-sub-name">${escapeHtml(translatedSub)}</div>` : ''}
          </div>
          <div class="trans-details">
            <span class="trans-title">${escapeHtml(displayTitle)}${isTransactionRecurring(t) ? '<i class="fa-solid fa-arrows-rotate recurring-arrows-icon" title="' + (state.lang === 'el' ? 'Επαναλαμβανόμενη κίνηση' : 'Recurring transaction') + '"></i>' : ''}${memberBadge}</span>
            <span class="trans-acc-label">${escapeHtml(accountText)}</span>
          </div>
        </div>
        <div class="${amountClass}">${getCurrencySymbol()} ${formatDisplayAmount(CurrencyService.displayAmount(t, displayCurrency), displayCurrency)}${getTxCurrencyLabel(t)}${getReliabilityBadge(t)}</div>`;
      fragment.appendChild(item);
    });
  });

  listContainer.replaceChildren(fragment);
}

// Get category display info (icon, name, color) from stored category or emoji map
// Normalize a category name for fuzzy matching: strip leading emoji, lowercase,
// remove Greek accents, and trim. Used to match e.g. "Αυτοκίνητο" against "🚗 ΑΥΤΟΚΙΝΗΤΟ".
function normalizeCategoryName(name) {
  if (!name) return '';
  return normalizeString(stripLeadingEmoji(String(name)).trim());
}

function getCategoryInfo(categoryName, transType) {
  if (!categoryName) return { icon: transType === 'income' ? '💰' : '💸', name: '', color: '#78909c' };

  // Try stored categories first (already cleaned)
  const stored = state.categories.find(c =>
    c.name && c.name.toUpperCase() === (categoryName || '').toUpperCase()
  );
  if (stored) return stored;

  // Try emoji map via codepoint
  const cp = getFirstEmojiCodepoint(categoryName);
  if (cp && CATEGORY_EMOJI_MAP[cp]) return CATEGORY_EMOJI_MAP[cp];

  // Strip and match
  const cleaned = stripLeadingEmoji(categoryName).trim();
  const cleaned2 = state.categories.find(c =>
    c.name && c.name.toUpperCase() === cleaned.toUpperCase()
  );
  if (cleaned2) return cleaned2;

  // Fuzzy match: normalize both sides (strip emoji + case/accents) so that
  // "Αυτοκίνητο" matches the stored "🚗 ΑΥΤΟΚΙΝΗΤΟ" category.
  const normInput = normalizeCategoryName(categoryName);
  if (normInput) {
    const fuzzy = state.categories.find(c => c.name && normalizeCategoryName(c.name) === normInput);
    if (fuzzy) return fuzzy;
  }

  return { icon: transType === 'income' ? '💰' : '💸', name: cleaned || categoryName, color: '#78909c' };
}

